"""Spec for is_palindrome: True exactly when the string equals its reverse.

Domain: lowercase strings, including the empty string (the unit tests use it).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "is_palindrome"

CLARIFICATIONS = [
    "Return a Python bool (True/False). The empty string is a palindrome.",
]

lower = st.text(alphabet="abc", max_size=20)
any_lower = st.one_of(lower, st.text(alphabet="abcdefghijklmnopqrstuvwxyz", max_size=20))


@st.composite
def palindromes(draw):
    half = draw(st.text(alphabet="abcxyz", max_size=15))
    mid = draw(st.sampled_from(["", "a", "q"]))
    return half + mid + half[::-1]


@st.composite
def near_palindromes(draw):
    p = draw(palindromes().filter(lambda s: len(s) >= 2))
    i = draw(st.integers(0, len(p) // 2 - 1))
    j = len(p) - 1 - i
    c = draw(st.sampled_from([ch for ch in "abcxyz" if ch != p[j]]))
    return p[:i] + c + p[i + 1:]


@prop("The result is a bool equal to whether the string reads the same backwards.", s=any_lower)
def matches_definition(f, s):
    r = f(s)
    assert r is True or r is False
    assert r == (s == s[::-1])


@prop("Every constructed palindrome returns True.", s=palindromes())
def palindromes_true(f, s):
    assert f(s) is True


@prop("Changing one character of a palindrome on one side only returns False.", s=near_palindromes())
def near_palindromes_false(f, s):
    assert f(s) is False


@prop("Reversing the string does not change the answer.", s=any_lower)
def reverse_invariant(f, s):
    assert f(s) == f(s[::-1])


@prop("The empty string and single characters are palindromes.", c=st.sampled_from("az"))
def trivial_palindromes(f, c):
    assert f("") is True
    assert f(c) is True

"""Spec for flatten_nested_list: all integers of an arbitrarily nested list, in left-to-right order.

Domain: lists whose elements are integers or (recursively) such lists; empty sublists allowed.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "flatten_nested_list"

CLARIFICATIONS = [
    "Empty sublists contribute nothing; return a new flat list of the integers.",
]

ints = st.integers(-1000, 1000)
nested = st.recursive(st.lists(ints, max_size=4), lambda inner: st.lists(st.one_of(ints, inner), max_size=5), max_leaves=30)


def flat(x):
    out = []
    for item in x:
        if isinstance(item, list):
            out.extend(flat(item))
        else:
            out.append(item)
    return out


@prop("The result is a list equal to the integers of the input in left-to-right order.", xs=nested)
def matches_definition(f, xs):
    r = f(xs)
    assert isinstance(r, list)
    assert r == flat(xs)


@prop("The result contains no lists.", xs=nested)
def is_flat(f, xs):
    assert all(not isinstance(x, list) for x in f(xs))


@prop("A flat list of integers is returned unchanged.", xs=st.lists(ints, max_size=20))
def flat_unchanged(f, xs):
    assert f(xs) == xs


@prop("Flattening distributes over concatenation.", a=nested, b=nested)
def concatenation(f, a, b):
    assert f(a + b) == f(a) + f(b)


@prop("Wrapping the input in extra levels of nesting does not change the result.", xs=nested, k=st.integers(1, 6))
def deep_wrapping(f, xs, k):
    w = xs
    for _ in range(k):
        w = [w]
    assert f(w) == flat(xs)


@prop("Lists of only empty sublists give an empty list.", k=st.integers(0, 5))
def only_empties(f, k):
    assert f([[] for _ in range(k)]) == []
    assert f([[[]], [], [[[]]]]) == []

reference_solution:
def flatten_nested_list(nested_list):
    """
    Flattens a nested list into a single list of integers, preserving order.

    :param nested_list: List containing integers or nested lists
    :return: Flattened list of integers
    """
    flat_list = []

    def flatten(sublist):
        for item in sublist:
            if isinstance(item, list):
                flatten(item)
            else:
                flat_list.append(item)

    flatten(nested_list)
    return flat_list

