spec:
"""Spec for num_islands: the number of 4-directionally connected components of '1' cells.

Domain: rectangular grids of '1'/'0' strings with 1..7 rows and 1..7 columns, plus the empty grid [].
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "num_islands"

CLARIFICATIONS = [
    "Return an int; an empty grid ([]) has 0 islands.",
]


@st.composite
def grids(draw):
    n = draw(st.integers(1, 7))
    m = draw(st.integers(1, 7))
    density = draw(st.sampled_from([0.0, 0.3, 0.5, 0.7, 1.0]))
    cells = draw(st.lists(st.floats(0, 1), min_size=n * m, max_size=n * m))
    return [["1" if cells[i * m + j] < density else "0" for j in range(m)] for i in range(n)]


def count_components(g):
    n, m = len(g), len(g[0])
    label = {}
    for i in range(n):
        for j in range(m):
            if g[i][j] == "1":
                label[(i, j)] = (i, j)
    changed = True
    while changed:
        changed = False
        for (i, j) in list(label):
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                q = (i + di, j + dj)
                if q in label and label[q] < label[(i, j)]:
                    label[(i, j)] = label[q]
                    changed = True
    return len(set(label.values()))


@prop("The result is an int equal to the number of 4-connected groups of land cells.", g=grids())
def matches_definition(f, g):
    r = f(g)
    assert isinstance(r, int) and not isinstance(r, bool)
    assert r == count_components(g)


@prop("A grid with no land has 0 islands.", n=st.integers(1, 8), m=st.integers(1, 8))
def all_water(f, n, m):
    assert f([["0"] * m for _ in range(n)]) == 0


@prop("A grid made entirely of land is one island.", n=st.integers(1, 8), m=st.integers(1, 8))
def all_land(f, n, m):
    assert f([["1"] * m for _ in range(n)]) == 1


@prop("Diagonally touching land cells form separate islands (checkerboard).", n=st.integers(1, 7), m=st.integers(1, 7))
def checkerboard(f, n, m):
    g = [["1" if (i + j) % 2 == 0 else "0" for j in range(m)] for i in range(n)]
    assert f(g) == sum(1 for i in range(n) for j in range(m) if (i + j) % 2 == 0)


@prop("Transposing or mirroring the grid does not change the count.", g=grids())
def symmetry_invariant(f, g):
    base = f(g)
    assert f([list(col) for col in zip(*g)]) == base
    assert f([row[::-1] for row in g]) == base
    assert f(g[::-1]) == base


@prop("The empty grid has 0 islands.", dummy=st.just(None))
def empty_grid(f, dummy):
    assert f([]) == 0

"""Spec for get_primes_desc: the primes of the input list (with multiplicity), sorted in descending order.

Domain: lists of integers, including 0, 1, negative numbers and duplicates (none of
0, 1 or negatives is prime by the stated definition), plus the empty list.
"""
from collections import Counter

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "get_primes_desc"

CLARIFICATIONS = [
    "Duplicate primes are kept: each occurrence in the input appears in the output.",
    "Zero, one and negative numbers are not prime.",
]


def is_prime(n):
    if n < 2:
        return False
    return all(n % d for d in range(2, n))


small_ints = st.integers(min_value=-20, max_value=120)
number_lists = st.one_of(
    st.lists(small_ints, max_size=30),
    st.lists(st.sampled_from([0, 1, 2, 3, 4, 9, 25, 49, 97, 91]), max_size=20),
    st.lists(st.integers(min_value=-5, max_value=5), max_size=20),
    st.lists(st.sampled_from([2, 3, 5, 7, 11, 13]), min_size=1, max_size=15),
)


@prop("The result is a list sorted in non-increasing order.", numbers=number_lists)
def sorted_descending(f, numbers):
    result = f(numbers)
    assert isinstance(result, list)
    assert all(result[i] >= result[i + 1] for i in range(len(result) - 1))


@prop("Every element of the result is a prime number.", numbers=number_lists)
def only_primes(f, numbers):
    assert all(is_prime(x) for x in f(numbers))


@prop("Every prime of the input appears in the result exactly as many times as in the input.", numbers=number_lists)
def all_primes_with_multiplicity(f, numbers):
    expected = Counter(x for x in numbers if is_prime(x))
    assert Counter(f(numbers)) == expected


@prop("The result equals the primes of the input sorted from largest to smallest.", numbers=number_lists)
def exact_result(f, numbers):
    assert f(numbers) == sorted((x for x in numbers if is_prime(x)), reverse=True)


@prop("Inputs without primes (including the empty list) give an empty list.",
      numbers=st.lists(st.sampled_from([-7, -2, -1, 0, 1, 4, 6, 8, 9, 15, 21, 25, 49, 91, 100]), max_size=15))
def no_primes_gives_empty(f, numbers):
    assert f(numbers) == []

reference_solution:
def get_primes_desc(numbers: list) -> list:
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    primes = [num for num in numbers if is_prime(num)]
    primes.sort(reverse=True)

    return primes

