reference_solution:
def exam_result(score):
    """
    Returns the result of an exam based on the given score.

    Parameters:
    score (int): The score obtained in the exam.

    Returns:
    str: The result of the exam ("Excellent", "Good", "Pass", "Fail").
    """
    if score >= 90:
        return "Excellent"
    elif score >= 70:
        return "Good"
    elif score >= 50:
        return "Pass"
    else:
        return "Fail"

