spec:
"""Spec for prime_factors: sorted list of the distinct primes dividing n; ValueError for invalid n.

Domain: valid inputs are ints 2..~10**6 (bounded so a trial-division reference stays fast).
Invalid inputs are ints <= 1, fractional floats and strings (as in the unit tests);
integral floats such as 4.0 are not generated.
"""
import math

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "prime_factors"

CLARIFICATIONS = [
    "Inputs that are not of type int (for example 1.5 or a string) must also raise the ValueError with that message.",
    "Return a list of ints.",
]

ERROR_MESSAGE = "Input must be a positive integer greater than 1"

SMALL_PRIMES = [p for p in range(2, 200) if all(p % d for d in range(2, int(p**0.5) + 1))]


def is_prime(k):
    if k < 2:
        return False
    return all(k % d for d in range(2, math.isqrt(k) + 1))


# Products of small primes (with repetition) give many repeated factors; plain
# integers cover primes and arbitrary composites.
products_of_primes = st.lists(st.sampled_from(SMALL_PRIMES), min_size=1, max_size=6).map(math.prod)
prime_powers = st.builds(pow, st.sampled_from(SMALL_PRIMES[:10]), st.integers(min_value=1, max_value=12)).filter(
    lambda k: k <= 10**6
)
valid_n = st.one_of(
    st.integers(min_value=2, max_value=20000),
    st.sampled_from(SMALL_PRIMES),
    prime_powers,
    products_of_primes,
    st.sampled_from([2, 3, 4, 6, 9997, 19997]),
)
small_n = st.integers(min_value=2, max_value=3000)

invalid_ints = st.integers(min_value=-10**6, max_value=1)
non_integers = st.one_of(
    st.floats(allow_nan=False, allow_infinity=False, min_value=-1e6, max_value=1e6).filter(lambda x: x != int(x)),
    st.text(max_size=5),
)


@prop("Integers less than or equal to 1 raise ValueError with the required message.", n=invalid_ints)
def rejects_small_integers(f, n):
    try:
        f(n)
    except ValueError as exc:
        assert ERROR_MESSAGE in str(exc)
    else:
        raise AssertionError(f"no ValueError for n={n!r}")


@prop("Non-integer inputs (fractional floats, strings) raise ValueError with the required message.", n=non_integers)
def rejects_non_integers(f, n):
    try:
        f(n)
    except ValueError as exc:
        assert ERROR_MESSAGE in str(exc)
    else:
        raise AssertionError(f"no ValueError for n={n!r}")


@prop("The result is a list sorted in strictly ascending order (no duplicates).", n=valid_n)
def strictly_ascending(f, n):
    result = f(n)
    assert isinstance(result, list)
    assert all(a < b for a, b in zip(result, result[1:]))


@prop("Every returned value is a prime that divides n.", n=valid_n)
def all_prime_divisors(f, n):
    for p in f(n):
        assert isinstance(p, int) and is_prime(p) and n % p == 0, p


@prop("The returned primes account for all of n: dividing them out repeatedly leaves 1.", n=valid_n)
def complete_factorization(f, n):
    result = f(n)
    rest = n
    for p in result:
        assert p >= 2
        while rest % p == 0:
            rest //= p
    assert rest == 1


@prop("On small inputs the result equals the brute-force list of prime divisors.", n=small_n)
def matches_brute_force(f, n):
    expected = [p for p in range(2, n + 1) if n % p == 0 and is_prime(p)]
    assert f(n) == expected

reference_solution:
def prime_factors(n: int) -> list:
    """
    Returns a list of unique prime factors of n in ascending order.
    """
    if not isinstance(n, int) or n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")

    factors = []
    divisor = 2

    while n > 1:
        if n % divisor == 0:
            if divisor not in factors:
                factors.append(divisor)
            n //= divisor
        else:
            divisor += 1

    return factors

spec:
"""Spec for evaluate_rpn: evaluate a Reverse Polish Notation token list, or raise ValueError("Invalid RPN expression").

Domain: token lists built from integer literals (possibly negative, e.g. "-3") and the
operators + - * /. Valid expressions are generated from random expression trees whose
divisions never divide by zero; operand magnitudes are bounded so intermediate values stay small.
Invalid expressions: empty list, leftover operands, missing operands, unknown operator tokens.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "evaluate_rpn"

CLARIFICATIONS = [
    "A token that is neither an integer nor one of + - * / makes the expression invalid.",
    "An empty expression is invalid.",
    "Inputs never divide by zero.",
]

MESSAGE = "Invalid RPN expression"


def trunc_div(a, b):
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b > 0) else -q


def apply(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    return trunc_div(a, b)


@st.composite
def expression(draw, max_leaves=8, ops="+-*/"):
    """Return (tokens, value) for a random valid expression tree."""
    n_leaves = draw(st.integers(min_value=1, max_value=max_leaves))

    def build(n):
        if n == 1:
            v = draw(st.integers(min_value=-9, max_value=9))
            return [str(v)], v
        k = draw(st.integers(min_value=1, max_value=n - 1))
        lt, lv = build(k)
        rt, rv = build(n - k)
        op = draw(st.sampled_from(ops))
        if op == "/" and rv == 0:
            op = draw(st.sampled_from("+-*"))
        return lt + rt + [op], apply(op, lv, rv)

    return build(n_leaves)


def raises_invalid(f, tokens):
    try:
        f(tokens)
    except ValueError as exc:
        assert str(exc) == MESSAGE, f"wrong message {str(exc)!r}"
        return
    raise AssertionError("expected ValueError")


@prop("A valid expression evaluates to the value of its expression tree.", case=expression())
def evaluates_correctly(f, case):
    tokens, value = case
    assert f(tokens) == value


@prop("A single integer token evaluates to that integer.", v=st.integers(min_value=-10**6, max_value=10**6))
def single_number(f, v):
    assert f([str(v)]) == v


@prop("Division truncates toward zero, also for negative operands.",
      a=st.integers(min_value=-100, max_value=100),
      b=st.integers(min_value=-20, max_value=20).filter(lambda x: x != 0))
def division_truncates(f, a, b):
    assert f([str(a), str(b), "/"]) == trunc_div(a, b)


@prop("Subtraction and division take the earlier operand as the left-hand side.",
      a=st.integers(min_value=-50, max_value=50), b=st.integers(min_value=1, max_value=9),
      op=st.sampled_from("-/"))
def operand_order(f, a, b, op):
    assert f([str(a), str(b), op]) == apply(op, a, b)


@prop("Too many operands (leftover values on the stack) raise ValueError(\"Invalid RPN expression\").",
      first=expression(max_leaves=4), second=expression(max_leaves=4))
def too_many_operands(f, first, second):
    raises_invalid(f, first[0] + second[0])


@prop("Too many operators, an unknown operator or an empty list raise ValueError(\"Invalid RPN expression\").",
      case=expression(max_leaves=5), kind=st.sampled_from(["extra_op", "unknown_op", "empty", "lone_op"]),
      op=st.sampled_from("+-*/"), bad=st.sampled_from(["%", "^", "x", "//"]))
def malformed_raises(f, case, kind, op, bad):
    tokens, _ = case
    if kind == "extra_op":
        tokens = tokens + [op]
    elif kind == "unknown_op":
        tokens = tokens + ["2", bad]
    elif kind == "empty":
        tokens = []
    else:
        tokens = [tokens[0], op] if len(tokens) == 1 else [op] + tokens
    raises_invalid(f, tokens)

reference_solution:
def evaluate_rpn(expression: list) -> int:
    """
    Evaluate the value of an arithmetic expression in Reverse Polish Notation.
    Valid operators are +, -, *, and /. Each operand may be an integer or another expression.
    Division should truncate towards zero.
    If the input is invalid, raise a ValueError with the message "Invalid RPN expression".
    """
    stack = []

    for token in expression:
        if token.lstrip('-').isdigit():  # This will cover negative numbers as well
            stack.append(int(token))
        else:
            if len(stack) < 2:
                raise ValueError("Invalid RPN expression")

            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))  # Ensure division truncates towards zero
            else:
                raise ValueError("Invalid RPN expression")

    if len(stack) != 1:
        raise ValueError("Invalid RPN expression")

    return stack[0]

