spec:
"""Spec for factorial_list: factorials of the list elements that are <= n, in input order.

Domain: lists of non-negative integers (0..25, duplicates allowed, any order) and a
non-negative limit n (0..25), including the empty list.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "factorial_list"

CLARIFICATIONS = [
    "Keep the factorials in the same order as the corresponding numbers in the input list, including duplicates.",
]


def fact(k):
    p = 1
    for i in range(2, k + 1):
        p *= i
    return p


nums = st.one_of(
    st.lists(st.integers(0, 25), max_size=20),
    st.lists(st.integers(0, 4), max_size=12),
)
limit = st.one_of(st.integers(0, 25), st.integers(0, 4))


@prop("The result has one entry per input number that is <= n.", numbers=nums, n=limit)
def correct_count(f, numbers, n):
    result = f(numbers, n)
    assert isinstance(result, list)
    assert len(result) == sum(1 for x in numbers if x <= n)


@prop("The result is the factorials of the numbers <= n, in input order (duplicates kept).", numbers=nums, n=limit)
def exact_result(f, numbers, n):
    assert f(numbers, n) == [fact(x) for x in numbers if x <= n]


@prop("A number equal to n is included.", numbers=nums, n=limit)
def boundary_inclusive(f, numbers, n):
    assert f(numbers + [n], n)[-1] == fact(n)


@prop("The factorial of 0 is 1.", count=st.integers(1, 5), n=st.integers(0, 10))
def zero_factorial(f, count, n):
    assert f([0] * count, n) == [1] * count


@prop("If no number is <= n (or the list is empty), the result is empty.",
      n=st.integers(0, 15), offsets=st.lists(st.integers(1, 10), max_size=10))
def none_qualify(f, n, offsets):
    assert f([n + d for d in offsets], n) == []

"""Spec for process_queries: apply updates and answer "max value reachable" queries on a grid.

A move goes to a 4-neighbour whose value is >= the current cell's value. Domain: grids
with 1..5 rows and columns, values in a small range (to create ties) or up to +-10**9;
queries use 1-based indices; there is at least one type-2 query.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "process_queries"

CLARIFICATIONS = [
    "Queries are lists: [1, i, j, val] for an update and [2, i, j] for a reachability query, with 1-based row i and column j.",
    "Return a list with the answers of the type-2 queries, in query order.",
    "Updates persist for all later queries.",
]


def reach_max(grid, i, j):
    rows, cols = len(grid), len(grid[0])
    seen = {(i, j)}
    stack = [(i, j)]
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen and grid[nr][nc] >= grid[r][c]:
                seen.add((nr, nc))
                stack.append((nr, nc))
    return max(grid[r][c] for r, c in seen)


@st.composite
def instances(draw, allow_updates=True):
    m = draw(st.integers(1, 5))
    n = draw(st.integers(1, 5))
    values = draw(st.sampled_from([st.integers(-3, 3), st.integers(0, 9), st.integers(-10**9, 10**9)]))
    grid = [[draw(values) for _ in range(n)] for _ in range(m)]
    queries = []
    for _ in range(draw(st.integers(1, 10))):
        i, j = draw(st.integers(1, m)), draw(st.integers(1, n))
        if allow_updates and draw(st.booleans()):
            queries.append([1, i, j, draw(values)])
        else:
            queries.append([2, i, j])
    if not any(q[0] == 2 for q in queries):
        queries.append([2, draw(st.integers(1, m)), draw(st.integers(1, n))])
    return m, n, grid, queries


def expected(grid, queries):
    g = [row[:] for row in grid]
    out = []
    for q in queries:
        if q[0] == 1:
            g[q[1] - 1][q[2] - 1] = q[3]
        else:
            out.append(reach_max(g, q[1] - 1, q[2] - 1))
    return out


@prop("The result has one answer per type-2 query.", inst=instances())
def answer_count(f, inst):
    m, n, grid, queries = inst
    result = f(m, n, grid, queries)
    assert isinstance(result, list)
    assert len(result) == sum(1 for q in queries if q[0] == 2)


@prop("Without updates, each answer is the maximum value reachable through non-decreasing moves.",
      inst=instances(allow_updates=False))
def static_answers(f, inst):
    m, n, grid, queries = inst
    assert f(m, n, grid, queries) == expected(grid, queries)


@prop("Without updates, every answer is at least the value of the starting cell.", inst=instances(allow_updates=False))
def at_least_start(f, inst):
    m, n, grid, queries = inst
    for q, ans in zip(queries, f(m, n, grid, queries)):
        assert ans >= grid[q[1] - 1][q[2] - 1]


@prop("Updates change the grid for all later queries.", inst=instances())
def with_updates(f, inst):
    m, n, grid, queries = inst
    assert f(m, n, grid, queries) == expected(grid, queries)


@prop("A cell with no neighbour of greater or equal value answers its own value.",
      m=st.integers(1, 5), n=st.integers(1, 5), data=st.data())
def isolated_peak(f, m, n, data):
    i, j = data.draw(st.integers(1, m)), data.draw(st.integers(1, n))
    grid = [[data.draw(st.integers(-100, 99)) for _ in range(n)] for _ in range(m)]
    grid[i - 1][j - 1] = 100
    assert f(m, n, grid, [[2, i, j]]) == [100]

reference_solution:
def process_queries(M, N, grid, queries):
    def bfs_max_value(i, j):
        from collections import deque
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        visited = [[False] * N for _ in range(M)]
        max_value = grid[i][j]
        queue = deque([(i, j)])
        visited[i][j] = True

        while queue:
            cur_i, cur_j = queue.popleft()
            for di, dj in directions:
                ni, nj = cur_i + di, cur_j + dj
                if 0 <= ni < M and 0 <= nj < N and not visited[ni][nj] and grid[ni][nj] >= grid[cur_i][cur_j]:
                    visited[ni][nj] = True
                    max_value = max(max_value, grid[ni][nj])
                    queue.append((ni, nj))

        return max_value

    results = []
    for query in queries:
        if query[0] == 1:
            _, i_q, j_q, val_q = query
            grid[i_q - 1][j_q - 1] = val_q
        elif query[0] == 2:
            _, i_q, j_q = query
            results.append(bfs_max_value(i_q - 1, j_q - 1))

    return results

spec:
"""Spec for min_meeting_rooms: the maximum number of half-open meetings [start, end) overlapping at once.

Domain: lists of up to 25 (start, end) tuples with 0 <= start < end <= 10000; the empty list is
covered by the unit tests although the constraints say N >= 1.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "min_meeting_rooms"

CLARIFICATIONS = [
    "The function receives the meetings directly as a list of (start, end) tuples and returns an int.",
    "A meeting that ends at time t does not conflict with a meeting that starts at time t.",
    "Return 0 for an empty list of meetings.",
]


def meeting(max_time):
    return (
        st.tuples(st.integers(0, max_time), st.integers(0, max_time))
        .filter(lambda t: t[0] != t[1])
        .map(lambda t: (min(t), max(t)))
    )


# A small time range forces many shared endpoints; a large one covers the full constraint range.
@st.composite
def identical(draw):
    return [draw(meeting(30))] * draw(st.integers(1, 25))


meetings_small = st.one_of(
    st.lists(meeting(30), min_size=1, max_size=25),
    st.lists(meeting(4), min_size=1, max_size=25),
    identical(),
    st.lists(meeting(30), min_size=1, max_size=1),
    st.lists(meeting(30), min_size=1, max_size=25).map(sorted),
)
meetings_any = st.one_of(meetings_small, st.lists(meeting(10000), min_size=1, max_size=25))


def brute_force(meetings):
    """Peak number of meetings in progress at any instant; a meeting ending at t frees its room for one starting at t."""
    times = {t for m in meetings for t in m}
    return max(sum(1 for s, e in meetings if s <= t < e) for t in times)


@st.composite
def back_to_back(draw):
    """A chain of meetings where each starts exactly when the previous one ends."""
    points = draw(st.lists(st.integers(0, 10000), min_size=2, max_size=20, unique=True))
    points.sort()
    meetings = list(zip(points, points[1:]))
    return draw(st.permutations(meetings))


@st.composite
def common_point(draw):
    """Meetings that all contain a shared instant t, so they pairwise conflict."""
    t = draw(st.integers(1, 9999))
    n = draw(st.integers(1, 20))
    return [(draw(st.integers(0, t)), draw(st.integers(t + 1, 10000))) for _ in range(n)]


@prop("An empty list of meetings needs 0 rooms.", meetings=st.just([]))
def empty_needs_zero(f, meetings):
    assert f(meetings) == 0


@prop("The result equals the peak number of simultaneously running meetings.", meetings=meetings_any)
def matches_peak_overlap(f, meetings):
    assert f(meetings) == brute_force(meetings)


@prop("Meetings that touch only at an endpoint can share one room.", meetings=back_to_back())
def back_to_back_share_room(f, meetings):
    assert f(list(meetings)) == 1


@prop("Meetings that all overlap at one instant each need their own room.", meetings=common_point())
def all_overlapping(f, meetings):
    assert f(meetings) == len(meetings)


@prop("Reordering the meetings does not change the result.", meetings=meetings_small, data=st.data())
def order_invariant(f, meetings, data):
    shuffled = list(data.draw(st.permutations(meetings)))
    assert f(meetings) == f(shuffled)


@prop(
    "Adding one meeting never decreases the result and raises it by at most one.",
    meetings=meetings_small,
    extra=meeting(30),
)
def adding_meeting_monotone(f, meetings, extra):
    before = f(meetings)
    after = f(meetings + [extra])
    assert before <= after <= before + 1

"""Spec for length_of_longest_substring: length of the longest substring with no repeated character.

Domain: strings of English letters, digits, symbols and spaces (case-sensitive), including the empty string.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "length_of_longest_substring"


def distinct(sub):
    return len(set(sub)) == len(sub)


def best(s):
    return max((j - i for i in range(len(s)) for j in range(i, len(s) + 1) if distinct(s[i:j])), default=0)


small_text = st.one_of(
    st.text(alphabet="abcd", max_size=25),
    st.text(alphabet="ab", max_size=25),
    st.text(alphabet="abcdefgh aA1!", max_size=30),
    st.builds(lambda c, n: c * n, st.sampled_from("a !"), st.integers(0, 15)),
)


@prop("The result equals the length of the longest substring without repeated characters.", s=small_text)
def is_longest(f, s):
    assert f(s) == best(s)


@prop("Some substring of the returned length has all distinct characters.", s=small_text)
def achievable(f, s):
    n = f(s)
    assert isinstance(n, int)
    assert 0 <= n <= len(s)
    assert any(distinct(s[i:i + n]) for i in range(len(s) - n + 1))


@prop("Every longer substring contains a repeated character.", s=small_text)
def no_longer(f, s):
    n = f(s)
    assert not any(distinct(s[i:i + n + 1]) for i in range(len(s) - n))


@prop("Reversing the string does not change the answer.", s=small_text)
def reverse_invariant(f, s):
    assert f(s) == f(s[::-1])


@prop("A string of all-distinct characters gives its full length.",
      s=st.lists(st.sampled_from("abcdefghijklmnopqrstuvwxyzABC0123456789!@# "), unique=True, max_size=30).map("".join))
def all_distinct(f, s):
    assert f(s) == len(s)


@prop("A string repeating one character gives 1, and the empty string gives 0.", c=st.sampled_from("ab !"), n=st.integers(0, 20))
def repeated_char(f, c, n):
    assert f(c * n) == min(n, 1)

reference_solution:
def length_of_longest_substring(s):
    """
    Finds the length of the longest substring without repeating characters.
    """
    char_map = {}
    left = 0
    longest = 0

    for right, char in enumerate(s):
        if char in char_map and char_map[char] >= left:
            left = char_map[char] + 1
        char_map[char] = right
        longest = max(longest, right - left + 1)

    return longest

