"""Spec for is_anagram_of_palindrome: True iff some rearrangement of the string is a palindrome.

Domain: strings of lowercase ASCII letters (length 0..1000), including the empty string.
"""
from itertools import permutations

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "is_anagram_of_palindrome"

CLARIFICATIONS = [
    "The empty string counts as an anagram of a palindrome (return True).",
    "Return a bool (True or False).",
]

lower = "abcdefghijklmnopqrstuvwxyz"

any_text = st.one_of(
    st.text(alphabet="ab", max_size=30),
    st.text(alphabet="abc", max_size=30),
    st.text(alphabet=lower, max_size=40),
    st.builds(lambda c, n: c * n, st.sampled_from("az"), st.integers(0, 50)),
)
tiny_text = st.one_of(st.text(alphabet="abc", max_size=6), st.text(alphabet="ab", max_size=6), st.text(alphabet=lower, max_size=5))


def brute(s):
    return any("".join(p) == "".join(p)[::-1] for p in set(permutations(s)))


@st.composite
def shuffled_palindromes(draw):
    half = draw(st.text(alphabet=draw(st.sampled_from(["ab", "abc", lower])), max_size=15))
    middle = draw(st.sampled_from(["", "a", "q", "z"]))
    pal = half + middle + half[::-1]
    return "".join(draw(st.permutations(list(pal))))


@st.composite
def two_odd_counts(draw):
    # Two distinct letters get odd counts, all others even: no palindrome arrangement exists.
    a, b = draw(st.lists(st.sampled_from(lower), min_size=2, max_size=2, unique=True))
    chars = [a] * (2 * draw(st.integers(0, 5)) + 1) + [b] * (2 * draw(st.integers(0, 5)) + 1)
    for c in draw(st.lists(st.sampled_from(lower), max_size=8)):
        chars += [c, c]
    if draw(st.booleans()):
        # A third odd-count letter keeps the answer False.
        c = draw(st.sampled_from([x for x in lower if x not in (a, b)]))
        chars += [c] * (2 * draw(st.integers(0, 3)) + 1)
    return "".join(draw(st.permutations(chars)))


@prop("The result agrees with trying every rearrangement of short strings.", s=tiny_text)
def matches_brute_force(f, s):
    assert f(s) == brute(s)


@prop("Any shuffle of a palindrome is reported True.", s=shuffled_palindromes())
def shuffled_palindrome_true(f, s):
    assert f(s) is True


@prop("A string in which two or more letters occur an odd number of times is reported False.", s=two_odd_counts())
def two_odd_letters_false(f, s):
    assert f(s) is False


@prop("The result is a bool and does not depend on the order of the characters.", s=any_text, data=st.data())
def bool_and_order_invariant(f, s, data):
    r = f(s)
    assert isinstance(r, bool)
    t = "".join(data.draw(st.permutations(list(s))))
    assert f(t) == r


@prop("The empty string and single characters are True; two different letters are False.", c=st.sampled_from(lower), d=st.sampled_from(lower))
def small_cases(f, c, d):
    assert f("") is True
    assert f(c) is True
    assert f(c + d) is (c == d)

"""Spec for has_increasing_triplet: per test case, "YES" iff the sequence has a strictly increasing subsequence of length 3.

Domain: T >= 1 test cases given as (N, A) tuples with N == len(A) >= 1 and 1 <= A_i <= 100000.
"""
from itertools import combinations

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "has_increasing_triplet"

CLARIFICATIONS = [
    "test_cases is a list of T tuples (N, A) where A is the list of N numbers.",
    "Return a list with one string per test case, in input order: \"YES\" if there are indices i < j < k with A[i] < A[j] < A[k], otherwise \"NO\".",
]


def brute(a):
    return "YES" if any(x < y < z for x, y, z in combinations(a, 3)) else "NO"


@st.composite
def sequence(draw, max_size=10):
    shape = draw(st.sampled_from(["random", "small", "sorted", "reverse", "equal"]))
    hi = 3 if shape == "small" else 100000
    a = draw(st.lists(st.integers(1, hi), min_size=1, max_size=max_size))
    if shape == "sorted":
        a.sort()
    elif shape == "reverse":
        a.sort(reverse=True)
    elif shape == "equal":
        a = [a[0]] * len(a)
    return a


def as_cases(seqs):
    return len(seqs), [(len(a), a) for a in seqs]


@prop("Each answer agrees with checking every triple of positions.", seqs=st.lists(sequence(), min_size=1, max_size=5))
def matches_brute_force(f, seqs):
    t, cases = as_cases(seqs)
    assert f(t, cases) == [brute(a) for a in seqs]


@prop("The result is a list of T strings, each \"YES\" or \"NO\".", seqs=st.lists(sequence(30), min_size=1, max_size=6))
def output_shape(f, seqs):
    t, cases = as_cases(seqs)
    r = f(t, cases)
    assert isinstance(r, list) and len(r) == t
    assert all(x in ("YES", "NO") for x in r)


@prop("Non-increasing sequences (including all-equal ones and sequences shorter than 3) give \"NO\".",
      a=st.lists(st.integers(1, 100000), min_size=1, max_size=40).map(lambda a: sorted(a, reverse=True)))
def non_increasing_is_no(f, a):
    assert f(1, [(len(a), a)]) == ["NO"]


@prop("A sequence that contains three strictly increasing values in order (possibly far apart) gives \"YES\".",
      data=st.data(), noise=st.lists(st.integers(1, 100000), max_size=20), vals=st.lists(st.integers(1, 100000), min_size=3, max_size=3, unique=True))
def planted_triplet_is_yes(f, data, noise, vals):
    x, y, z = sorted(vals)
    a = list(noise)
    positions = sorted(data.draw(st.lists(st.integers(0, len(a)), min_size=3, max_size=3)))
    for offset, (pos, v) in enumerate(zip(positions, (x, y, z))):
        a.insert(pos + offset, v)
    assert f(1, [(len(a), a)]) == ["YES"]


@prop("Answers are per test case: a batch gives the same answers as the cases run one by one.",
      seqs=st.lists(sequence(), min_size=2, max_size=6))
def cases_independent(f, seqs):
    t, cases = as_cases(seqs)
    assert f(t, cases) == [f(1, [c])[0] for c in cases]

reference_solution:
def has_increasing_triplet(T, test_cases):
    results = []

    for i in range(T):
        N, A = test_cases[i]
        if N < 3:
            results.append("NO")
            continue

        first = float('inf')
        second = float('inf')

        for number in A:
            if number <= first:
                first = number
            elif number <= second:
                second = number
            else:
                results.append("YES")
                break
        else:
            results.append("NO")

    return results

