spec:
"""Spec for num_distinct_regions: number of 4-connected components of '1' cells in a grid of '0'/'1' characters.

Domain: rectangular lists of lists of the single-character strings '0' and '1'; [] and [[]] are allowed (answer 0).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "num_distinct_regions"

CLARIFICATIONS = ["The grid is a list of rows of '0'/'1' strings; an empty grid ([] or [[]]) has 0 regions. Return an int."]


@st.composite
def grids(draw, max_side=7):
    m = draw(st.integers(1, max_side))
    n = draw(st.integers(1, max_side))
    p = draw(st.sampled_from([0.2, 0.5, 0.8]))
    cells = draw(st.lists(st.floats(0, 1), min_size=m * n, max_size=m * n))
    return [["1" if cells[i * n + j] < p else "0" for j in range(n)] for i in range(m)]


def count_components(grid):
    """Union-find over '1' cells, joining right and down neighbours."""
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])
    parent = {(i, j): (i, j) for i in range(m) for j in range(n) if grid[i][j] == "1"}

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    for (i, j) in list(parent):
        for nb in ((i + 1, j), (i, j + 1)):
            if nb in parent:
                parent[find(nb)] = find((i, j))
    return len({find(c) for c in parent})


@prop("The count equals the number of 4-connected groups of '1' cells (diagonal neighbours are not connected).", grid=grids())
def matches_component_count(f, grid):
    assert f(grid) == count_components(grid)


@prop("Transposing or mirroring the grid does not change the count.", grid=grids())
def symmetry_invariant(f, grid):
    r = f(grid)
    assert isinstance(r, int)
    assert f([list(col) for col in zip(*grid)]) == r
    assert f([row[::-1] for row in grid]) == r


@prop("A checkerboard of '1's (only diagonal contacts) has one region per '1' cell.", m=st.integers(1, 7), n=st.integers(1, 7), parity=st.integers(0, 1))
def checkerboard(f, m, n, parity):
    grid = [["1" if (i + j) % 2 == parity else "0" for j in range(n)] for i in range(m)]
    assert f(grid) == sum(row.count("1") for row in grid)


@prop("An all-'0' grid has 0 regions and an all-'1' grid has 1.", m=st.integers(1, 8), n=st.integers(1, 8))
def uniform_grids(f, m, n):
    assert f([["0"] * n for _ in range(m)]) == 0
    assert f([["1"] * n for _ in range(m)]) == 1


@prop("Empty grids [] and [[]] have 0 regions.", dummy=st.just(None))
def empty_grids(f, dummy):
    assert f([]) == 0
    assert f([[]]) == 0

reference_solution:
def num_distinct_regions(grid):
    """
    Returns the number of distinct regions of '1's in the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]

    def dfs(x, y):
        # Stack for Depth-First Search (DFS)
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == '1':
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    region_count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not visited[i][j]:
                region_count += 1
                visited[i][j] = True
                dfs(i, j)

    return region_count

spec:
"""Spec for max_sum_k_consecutive: maximum sum over all windows of k consecutive elements.

Domain: arr is a list of integers (negatives allowed); k is an integer. When no window of
k elements exists (arr empty, k < 1 or k > len(arr)) the result is 0, following the
reference solution and unit tests.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "max_sum_k_consecutive"

CLARIFICATIONS = [
    "Return 0 if arr is empty, if k < 1, or if k is greater than len(arr).",
    "Return the sum as an int.",
]

ints = st.integers(min_value=-1000, max_value=1000)

arrays = st.one_of(
    st.lists(ints, min_size=1, max_size=30),
    st.lists(st.integers(min_value=-1000, max_value=-1), min_size=1, max_size=30),
    st.lists(st.integers(min_value=-3, max_value=3), min_size=1, max_size=30),
    st.builds(lambda x, n: [x] * n, ints, st.integers(min_value=1, max_value=10)),
    st.lists(ints, min_size=1, max_size=30).map(sorted),
    st.lists(ints, min_size=1, max_size=30).map(lambda xs: sorted(xs, reverse=True)),
)


@st.composite
def array_and_valid_k(draw):
    arr = draw(arrays)
    k = draw(st.one_of(st.just(1), st.just(len(arr)), st.integers(min_value=1, max_value=len(arr))))
    return arr, k


@st.composite
def array_and_invalid_k(draw):
    arr = draw(st.one_of(st.just([]), st.lists(ints, min_size=1, max_size=10)))
    k = draw(st.one_of(st.integers(min_value=-3, max_value=0), st.integers(min_value=len(arr) + 1, max_value=len(arr) + 5)))
    return arr, k


def window_sums(arr, k):
    return [sum(arr[i:i + k]) for i in range(len(arr) - k + 1)]


@prop("The result is an int equal to the sum of some k consecutive elements of arr.", case=array_and_valid_k())
def is_achievable(f, case):
    arr, k = case
    result = f(arr, k)
    assert isinstance(result, int)
    assert result in window_sums(arr, k)


@prop("The result is at least the sum of every window of k consecutive elements.", case=array_and_valid_k())
def is_upper_bound(f, case):
    arr, k = case
    result = f(arr, k)
    assert all(result >= s for s in window_sums(arr, k))


@prop("When no window of k elements exists (empty list, k < 1, or k > len(arr)), the result is 0.", case=array_and_invalid_k())
def no_window_returns_zero(f, case):
    arr, k = case
    assert f(arr, k) == 0


@prop("Reversing the list does not change the answer.", case=array_and_valid_k())
def reversal_invariant(f, case):
    arr, k = case
    assert f(arr, k) == f(arr[::-1], k)


@prop("With k == len(arr) the answer is the sum of the whole list.", arr=arrays)
def full_window_is_total(f, arr):
    assert f(arr, len(arr)) == sum(arr)


@prop("With k == 1 the answer is the largest element.", arr=arrays)
def unit_window_is_max(f, arr):
    assert f(arr, 1) == max(arr)

