spec:
"""Spec for restore_string: the decoded string has s[i] at position indices[i].

Domain: s is a non-empty string of lowercase letters and indices is a permutation of
range(len(s)). Empty strings are not generated (the statement and tests do not cover them).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "restore_string"

CLARIFICATIONS = [
    "indices is a permutation of 0..len(s)-1.",
    "Return the decoded string as a str.",
]

letters = st.one_of(
    st.text(alphabet="abcdefghijklmnopqrstuvwxyz", min_size=1, max_size=26),
    st.text(alphabet="ab", min_size=1, max_size=26),
    st.builds(lambda c, n: c * n, st.sampled_from("xyz"), st.integers(min_value=1, max_value=10)),
)


@st.composite
def encoded(draw):
    s = draw(letters)
    n = len(s)
    indices = draw(st.one_of(
        st.permutations(list(range(n))),
        st.just(list(range(n))),
        st.just(list(range(n - 1, -1, -1))),
        st.integers(min_value=0, max_value=n - 1).map(lambda r: [(i + r) % n for i in range(n)]),
    ))
    return s, list(indices)


@prop("The result is a str of the same length as s.", case=encoded())
def same_length_string(f, case):
    s, indices = case
    result = f(s, indices)
    assert isinstance(result, str)
    assert len(result) == len(s)


@prop("Each character s[i] appears at position indices[i] of the result.", case=encoded())
def characters_placed(f, case):
    s, indices = case
    result = f(s, indices)
    assert all(result[indices[i]] == s[i] for i in range(len(s)))


@prop("The result uses exactly the same multiset of characters as s.", case=encoded())
def is_permutation_of_s(f, case):
    s, indices = case
    assert sorted(f(s, indices)) == sorted(s)


@prop("The identity permutation returns s unchanged.", s=letters)
def identity_is_noop(f, s):
    assert f(s, list(range(len(s)))) == s


@prop("The reversed permutation returns s reversed.", s=letters)
def reverse_permutation_reverses(f, s):
    assert f(s, list(range(len(s) - 1, -1, -1))) == s[::-1]

"""Spec for minMeetingRooms: the minimum number of rooms so that no two meetings sharing a room overlap.

Domain: a list (possibly empty) of (start, end) integer tuples with 0 <= start < end; intervals are half-open,
so a meeting ending at t and another starting at t can share a room.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "minMeetingRooms"

CLARIFICATIONS = ["Return an int; an empty list of meetings needs 0 rooms."]


@st.composite
def meetings(draw, min_size=0):
    hi = draw(st.sampled_from([5, 20, 1000]))
    raw = draw(st.lists(st.tuples(st.integers(0, hi), st.integers(1, max(1, hi // 2))), min_size=min_size, max_size=12))
    return [(s, s + d) for s, d in raw]


def max_overlap(intervals):
    # The busiest moment always coincides with some meeting's start.
    return max((sum(s <= t < e for s, e in intervals) for t, _ in intervals), default=0)


@prop("The result equals the largest number of meetings in progress at the same moment.", ms=meetings())
def matches_max_overlap(f, ms):
    assert f(ms) == max_overlap(ms)


@prop("Meetings that only touch end-to-start (half-open intervals) fit in one room.",
      lengths=st.lists(st.integers(1, 10), min_size=1, max_size=10), start=st.integers(0, 100))
def back_to_back_one_room(f, lengths, start):
    ms, t = [], start
    for d in lengths:
        ms.append((t, t + d))
        t += d
    assert f(ms) == 1


@prop("k copies of the same meeting need k rooms.", s=st.integers(0, 100), d=st.integers(1, 50), k=st.integers(1, 10))
def identical_meetings(f, s, d, k):
    assert f([(s, s + d)] * k) == k


@prop("Shifting all meetings by the same amount or reordering them does not change the answer.", ms=meetings(1), shift=st.integers(0, 1000), data=st.data())
def shift_and_order_invariant(f, ms, shift, data):
    r = f(ms)
    assert isinstance(r, int)
    assert f([(s + shift, e + shift) for s, e in ms]) == r
    assert f(data.draw(st.permutations(ms))) == r


@prop("No meetings need 0 rooms and a single meeting needs 1.", s=st.integers(0, 100), d=st.integers(1, 50))
def empty_and_single(f, s, d):
    assert f([]) == 0
    assert f([(s, s + d)]) == 1

