reference_solution:
def length_of_longest_substring(s):
    """
    Given a string s, return the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = i
        longest = max(longest, i - start + 1)

    return longest

spec:
"""Spec for find_order: a topological order of the projects, or [] if the dependencies contain a cycle.

Domain: projects is a list of unique integer IDs; every dependency [a, b] refers to IDs in projects
(duplicate dependencies and self-dependencies may occur; a self-dependency is a cycle).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "find_order"

CLARIFICATIONS = [
    "Every ID in dependencies appears in projects; the returned order must contain every project exactly once.",
    "A project that depends on itself, or any dependency cycle, means no valid order exists, so return [].",
]


@st.composite
def dag_case(draw):
    """Projects with dependencies that always admit a valid order."""
    ids = draw(st.lists(st.integers(-50, 50), unique=True, min_size=1, max_size=9))
    hidden = draw(st.permutations(ids))
    n = len(hidden)
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    density = draw(st.sampled_from([0.0, 0.2, 0.5, 1.0]))
    chosen = [p for p in pairs if draw(st.floats(0, 1)) < density] if pairs else []
    deps = [[hidden[i], hidden[j]] for i, j in chosen]
    if deps and draw(st.booleans()):
        deps.append(list(draw(st.sampled_from(deps))))
    deps = draw(st.permutations(deps))
    return list(ids), [list(d) for d in deps]


@st.composite
def cyclic_case(draw):
    """Projects whose dependencies definitely contain a cycle."""
    ids, deps = draw(dag_case())
    cycle = draw(st.lists(st.sampled_from(ids), unique=True, min_size=1, max_size=len(ids)))
    for k in range(len(cycle)):
        deps.append([cycle[k], cycle[(k + 1) % len(cycle)]])
    deps = draw(st.permutations(deps))
    return ids, [list(d) for d in deps]


def has_cycle(ids, deps):
    adj = {p: set() for p in ids}
    for a, b in deps:
        adj[a].add(b)
    for start in ids:
        seen, stack = set(), list(adj[start])
        while stack:
            x = stack.pop()
            if x == start:
                return True
            if x not in seen:
                seen.add(x)
                stack.extend(adj[x])
    return False


any_case = st.one_of(dag_case(), cyclic_case())


@prop("For acyclic dependencies the result is a list containing every project exactly once.", case=dag_case())
def acyclic_is_permutation(f, case):
    ids, deps = case
    r = f(ids, deps)
    assert isinstance(r, list)
    assert sorted(r) == sorted(ids)


@prop("For acyclic dependencies every dependency [a, b] has a placed before b.", case=dag_case())
def acyclic_respects_dependencies(f, case):
    ids, deps = case
    r = f(ids, deps)
    pos = {p: i for i, p in enumerate(r)}
    assert all(a in pos and b in pos and pos[a] < pos[b] for a, b in deps)


@prop("When the dependencies contain a cycle the result is an empty list.", case=cyclic_case())
def cycle_gives_empty(f, case):
    ids, deps = case
    assert f(ids, deps) == []


@prop("The result is empty exactly when the dependencies contain a cycle.", case=any_case)
def empty_iff_cycle(f, case):
    ids, deps = case
    assert (f(ids, deps) == []) == has_cycle(ids, deps)


@prop("With no dependencies every project is returned once; a single project returns [project].",
      ids=st.lists(st.integers(-50, 50), unique=True, min_size=1, max_size=10))
def no_dependencies(f, ids):
    r = f(ids, [])
    assert sorted(r) == sorted(ids)
    assert f([ids[0]], []) == [ids[0]]

"""Spec for third_max: the third largest distinct value, or the maximum if fewer than three distinct values exist.

Domain: nums is a non-empty list of integers (negatives allowed). Empty input is not
generated: the statement does not define it and the reference raises on it.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "third_max"

CLARIFICATIONS = [
    "nums contains at least one element.",
]

nums_lists = st.one_of(
    st.lists(st.integers(min_value=-10, max_value=10), min_size=1, max_size=20),
    st.lists(st.integers(min_value=-2, max_value=2), min_size=1, max_size=20),
    st.lists(st.integers(min_value=-1000, max_value=1000), unique=True, min_size=1, max_size=6),
    st.lists(st.integers(min_value=-10, max_value=10), min_size=1, max_size=20).map(sorted),
    st.lists(st.integers(min_value=-10, max_value=10), min_size=1, max_size=20).map(lambda xs: sorted(xs, reverse=True)),
)


@st.composite
def few_distinct(draw):
    values = draw(st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=1, max_size=2))
    xs = draw(st.lists(st.sampled_from(values), min_size=1, max_size=10))
    return list(draw(st.permutations(xs + values)))


@st.composite
def many_distinct(draw):
    values = draw(st.lists(st.integers(min_value=-100, max_value=100), unique=True, min_size=3, max_size=8))
    xs = draw(st.lists(st.sampled_from(values), max_size=10))
    return list(draw(st.permutations(xs + values)))


@prop("The result is an element of nums.", nums=nums_lists)
def is_member(f, nums):
    assert f(nums) in nums


@prop("With at least three distinct values, exactly two distinct values are greater than the result.",
      nums=many_distinct())
def is_third_distinct_max(f, nums):
    r = f(nums)
    assert r in nums
    assert len({x for x in nums if x > r}) == 2


@prop("With fewer than three distinct values, the result is the maximum.", nums=few_distinct())
def fewer_than_three_returns_max(f, nums):
    assert f(nums) == max(nums)


@prop("Reordering the array does not change the answer.", nums=nums_lists, data=st.data())
def order_invariant(f, nums, data):
    shuffled = list(data.draw(st.permutations(nums)))
    assert f(shuffled) == f(nums)


@prop("Appending copies of existing elements does not change the answer.", nums=nums_lists, data=st.data())
def duplicate_invariant(f, nums, data):
    extra = data.draw(st.lists(st.sampled_from(nums), min_size=1, max_size=10))
    assert f(nums + extra) == f(nums)

reference_solution:
def third_max(nums):
    """
    Finds the third distinct maximum number in the array nums.
    If the third distinct maximum does not exist, returns the maximum number.
    """
    distinct_nums = set(nums)

    if len(distinct_nums) < 3:
        return max(distinct_nums)

    distinct_nums.remove(max(distinct_nums))
    distinct_nums.remove(max(distinct_nums))

    return max(distinct_nums)

