spec:
"""Spec for can_construct_target: whether target is a concatenation of words (each reusable any number of times).

Domain: words is a non-empty list of non-empty lowercase strings; target is a lowercase string,
including the empty string (unit tests: empty target -> True).
"""
from functools import lru_cache

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "can_construct_target"

CLARIFICATIONS = [
    "Return a bool (True or False).",
    "An empty target can always be constructed (concatenating zero words), so return True.",
]

word_lists = st.lists(st.text(alphabet="ab", min_size=1, max_size=4), min_size=1, max_size=5)


def constructible(words, target):
    @lru_cache(maxsize=None)
    def go(k):
        if k == len(target):
            return True
        return any(target.startswith(w, k) and go(k + len(w)) for w in words)
    return go(0)


@st.composite
def built_case(draw):
    words = draw(word_lists)
    picks = draw(st.lists(st.sampled_from(words), min_size=1, max_size=8))
    return words, "".join(picks)


@st.composite
def random_case(draw):
    words = draw(word_lists)
    target = draw(st.text(alphabet="ab", min_size=1, max_size=14))
    return words, target


@prop("The result is a bool that matches whether target splits into words.", case=st.one_of(built_case(), random_case()))
def matches_definition(f, case):
    words, target = case
    r = f(words, target)
    assert isinstance(r, bool)
    assert r == constructible(words, target)


@prop("A target built by concatenating words from the list is constructible.", case=built_case())
def concatenations_are_constructible(f, case):
    words, target = case
    assert f(words, target) is True


@prop("A target containing a letter that no word contains is not constructible.",
      case=random_case(), pos=st.integers(0, 20))
def foreign_letter_rejected(f, case, pos):
    words, target = case
    k = pos % (len(target) + 1)
    assert f(words, target[:k] + "c" + target[k:]) is False


@prop("A target that can only be split up to a leftover suffix is not constructible.",
      case=built_case(), extra=st.text(alphabet="ab", min_size=1, max_size=3))
def leftover_rejected(f, case, extra):
    words, target = case
    t = target + extra
    assert f(words, t) is constructible(words, t)


@prop("The empty target is constructible; a single word is constructible from itself.", case=built_case())
def degenerate_cases(f, case):
    words, _ = case
    assert f(words, "") is True
    assert f([words[0]], words[0] * 3) is True

reference_solution:
def can_construct_target(words, target):
    """
    Determine if `target` can be constructed by concatenating words from `words`,
    each word can be used any number of times.
    """
    dp = [False] * (len(target) + 1)
    dp[0] = True

    for i in range(1, len(target) + 1):
        for word in words:
            if i >= len(word) and dp[i - len(word)] and target[i-len(word):i] == word:
                dp[i] = True
                break

    return dp[len(target)]

spec:
"""Spec for find_groupings: every non-empty subset of friends 1..n, each listed once.

Domain: 0 <= n <= 8. Output order (from the reference and unit tests): groups by increasing size,
groups of equal size in lexicographic order, IDs within a group increasing.
"""
from itertools import combinations

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "find_groupings"

CLARIFICATIONS = [
    "Return a list of lists; list the IDs inside each group in increasing order.",
    "Order the groups by increasing size, and groups of the same size lexicographically (e.g. for n = 3: [[1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]]); the example ordering in the statement is only illustrative.",
    "Return [] for n = 0.",
]

sizes = st.integers(0, 8)


@prop("The groups are exactly the non-empty subsets of 1..n, ignoring order.", n=sizes)
def correct_subsets(f, n):
    r = f(n)
    got = {frozenset(g) for g in r}
    want = {frozenset(c) for k in range(1, n + 1) for c in combinations(range(1, n + 1), k)}
    assert got == want


@prop("No group is repeated, the result has 2**n - 1 groups and every group is a list.", n=sizes)
def no_duplicates(f, n):
    r = f(n)
    assert isinstance(r, list) and all(isinstance(g, list) for g in r)
    assert len(r) == 2 ** n - 1
    assert len({frozenset(g) for g in r}) == len(r)
    assert all(len(set(g)) == len(g) for g in r)


@prop("IDs inside every group are in increasing order.", n=sizes)
def groups_sorted(f, n):
    assert all(list(g) == sorted(g) for g in f(n))


@prop("Groups are ordered by size, then lexicographically.", n=sizes)
def groups_ordered(f, n):
    keys = [(len(g), list(g)) for g in f(n)]
    assert keys == sorted(keys)


@prop("n = 0 gives [] and n = 1 gives [[1]].", dummy=st.just(None))
def small_cases(f, dummy):
    assert f(0) == []
    assert f(1) == [[1]]

