spec:
"""Spec for is_subsequence: whether s1 can be obtained from s2 by deleting characters without reordering.

Domain: lowercase strings, including empty strings (unit tests cover "" for both arguments).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "is_subsequence"

CLARIFICATIONS = [
    "Return a bool (True or False).",
    "The empty string is a subsequence of every string (including the empty string).",
]

small = st.text(alphabet="abc", max_size=10)
tiny = st.text(alphabet="ab", max_size=6)


def subseq(a, b):
    """Brute force: does some set of positions in b spell a in order?"""
    def go(i, j):
        if i == len(a):
            return True
        return any(b[k] == a[i] and go(i + 1, k + 1) for k in range(j, len(b)))
    return go(0, 0)


@st.composite
def derived_pair(draw):
    s2 = draw(st.text(alphabet="abcd", max_size=15))
    keep = draw(st.lists(st.booleans(), min_size=len(s2), max_size=len(s2)))
    return "".join(c for c, k in zip(s2, keep) if k), s2


@prop("The result is a bool matching whether s1 is a subsequence of s2.", s1=tiny, s2=small)
def matches_definition(f, s1, s2):
    r = f(s1, s2)
    assert isinstance(r, bool)
    assert r == subseq(s1, s2)


@prop("A string obtained by deleting characters from s2 is a subsequence of s2.", pair=derived_pair())
def deletions_are_subsequences(f, pair):
    s1, s2 = pair
    assert f(s1, s2) is True


@prop("A string longer than s2 is never a subsequence of it.", s2=small, extra=st.text(alphabet="abc", min_size=1, max_size=4))
def longer_is_not(f, s2, extra):
    assert f(s2 + extra, s2) is False
    assert f(extra + s2, s2) is False


@prop("Order matters: a reordering that is not a subsequence is rejected.", pair=derived_pair())
def order_matters(f, pair):
    s1, s2 = pair
    t = s1[::-1]
    assert f(t, s2) is subseq(t, s2)


@prop("Multiplicity matters: needing more copies of a character than s2 has is rejected.", s2=small, c=st.sampled_from("abc"))
def multiplicity_matters(f, s2, c):
    assert f(c * (s2.count(c) + 1), s2) is False
    assert f(c * s2.count(c), s2) is True


@prop("Empty s1 is always a subsequence; non-empty s1 is never a subsequence of the empty string.", s=small)
def empty_cases(f, s):
    assert f("", s) is True
    assert f(s, s) is True
    if s:
        assert f(s, "") is False

"""Spec for trap: total rain water trapped by an elevation map of unit-width bars.

Domain: lists of non-negative integers, including the empty list.
Water above bar i is min(max height to its left incl. i, max height to its right incl. i) - height[i].
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "trap"

CLARIFICATIONS = ["Return 0 for an empty list."]

heights = st.one_of(
    st.lists(st.integers(0, 10), max_size=30),
    st.lists(st.integers(0, 2), max_size=30),
    st.lists(st.integers(0, 1000), max_size=30),
    st.lists(st.integers(0, 20), max_size=30).map(sorted),
    st.lists(st.integers(0, 20), max_size=30).map(lambda xs: sorted(xs, reverse=True)),
    st.builds(lambda h, n: [h] * n, st.integers(0, 10), st.integers(0, 15)),
)


def water(hs):
    return sum(max(0, min(max(hs[:i + 1]), max(hs[i:])) - hs[i]) for i in range(len(hs)))


@prop("The result is an int equal to the trapped water computed bar by bar.", hs=heights)
def matches_definition(f, hs):
    r = f(hs)
    assert isinstance(r, int) and not isinstance(r, bool)
    assert r == water(hs)


@prop("Reversing the elevation map does not change the trapped water.", hs=heights)
def reverse_invariant(f, hs):
    assert f(hs) == f(hs[::-1])


@prop("Monotone (sorted or reverse-sorted) maps trap no water.", hs=st.lists(st.integers(0, 50), max_size=30))
def monotone_traps_nothing(f, hs):
    assert f(sorted(hs)) == 0
    assert f(sorted(hs, reverse=True)) == 0


@prop("A pit between two walls holds min(walls) - depth per bar.",
      a=st.integers(0, 100), b=st.integers(0, 100), inner=st.lists(st.integers(0, 100), min_size=1, max_size=8))
def single_basin(f, a, b, inner):
    lo = min(a, b)
    inner = [min(x, lo) for x in inner]
    assert f([a] + inner + [b]) == sum(lo - x for x in inner)


@prop("Empty, single-bar and two-bar maps trap no water.", a=st.integers(0, 100), b=st.integers(0, 100))
def degenerate_cases(f, a, b):
    assert f([]) == 0
    assert f([a]) == 0
    assert f([a, b]) == 0

