@prop("Two buildings give min(a, b) and a single building gives 0.", a=st.integers(0, 10**6), b=st.integers(0, 10**6))
def tiny_inputs(f, a, b):
    assert f([a, b]) == min(a, b)
    assert f([a]) == 0

