spec:
"""Spec for group_anagrams: partition the words into groups of mutual anagrams.

Domain: lists of distinct non-empty strings over a small mixed-case alphabet, including the empty list.
Anagrams are case-sensitive. Order (from the reference and unit tests): groups appear in the order
of their first word in the input; inside a group, words keep their input order.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "group_anagrams"

CLARIFICATIONS = [
    "Letters are case-sensitive: 'bAt' and 'tab' are not anagrams.",
    "A word with no anagram in the list forms a group by itself; return [] for an empty list.",
    "Order the groups by the position of their first word in the input, and keep the words inside each group in input order.",
]


@st.composite
def word_lists(draw):
    bases = draw(st.lists(st.text(alphabet="abcA", min_size=1, max_size=4), min_size=0, max_size=5))
    words = []
    for b in bases:
        words.append(b)
        for _ in range(draw(st.integers(0, 3))):
            words.append("".join(draw(st.permutations(list(b)))))
    words = draw(st.permutations(words))
    out, seen = [], set()
    for w in words:
        if w not in seen:
            seen.add(w)
            out.append(w)
    return out


def key(w):
    return tuple(sorted(w))


@prop("The result is a list of lists that together contain every input word exactly once.", words=word_lists())
def is_partition(f, words):
    r = f(words)
    assert isinstance(r, list) and all(isinstance(g, list) for g in r)
    assert sorted(w for g in r for w in g) == sorted(words)
    assert all(len(g) > 0 for g in r)


@prop("All words in the same group are anagrams of each other.", words=word_lists())
def groups_are_anagrams(f, words):
    assert all(len({key(w) for w in g}) == 1 for g in f(words))


@prop("Anagrams are never split across different groups.", words=word_lists())
def anagrams_not_split(f, words):
    keys = [key(g[0]) for g in f(words) if g]
    assert len(keys) == len(set(keys))


@prop("Groups follow first appearance in the input and words inside a group keep input order.", words=word_lists())
def order_preserved(f, words):
    r = f(words)
    pos = {w: i for i, w in enumerate(words)}
    assert all([pos[w] for w in g] == sorted(pos[w] for w in g) for g in r)
    firsts = [min(pos[w] for w in g) for g in r if g]
    assert firsts == sorted(firsts)


@prop("Case matters, words without anagrams stand alone, and an empty list gives [].",
      w=st.text(alphabet="abc", min_size=2, max_size=5))
def edge_cases(f, w):
    assert f([]) == []
    upper = w[0].upper() + w[1:][::-1]
    assert f([w, upper]) == [[w], [upper]]
    assert f([w]) == [[w]]

"""Spec for can_make_bouquets: is there a day on which m disjoint bouquets of k adjacent bloomed flowers can be picked?

Domain: flowers is a non-empty list of positive integers (bloom days), k >= 1, m >= 1.
On day d a flower has bloomed iff its bloom day <= d; each flower goes into at most one bouquet.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "can_make_bouquets"

CLARIFICATIONS = [
    "A flower can be picked on day d once its blooming day is <= d, and each flower can be used in at most one bouquet.",
    "flowers is non-empty and k, m >= 1; return a bool.",
]

days = st.one_of(st.integers(1, 5), st.integers(1, 10**9))


@st.composite
def cases(draw):
    flowers = draw(st.lists(days, min_size=1, max_size=15))
    k = draw(st.integers(1, 6))
    m = draw(st.integers(1, 6))
    return flowers, k, m


def max_bouquets_on(flowers, k, day):
    """Best number of disjoint bouquets: split bloomed flowers into maximal adjacent runs."""
    total, run = 0, 0
    for b in flowers + [day + 1]:
        if b <= day:
            run += 1
        else:
            total += run // k
            run = 0
    return total


def possible(flowers, k, m):
    return any(max_bouquets_on(flowers, k, d) >= m for d in set(flowers))


@prop("The result is a bool telling whether some day allows m bouquets.", case=cases())
def matches_definition(f, case):
    flowers, k, m = case
    r = f(flowers, k, m)
    assert isinstance(r, bool)
    assert r == possible(flowers, k, m)


@prop("If m bouquets are possible then fewer bouquets are possible too.", case=cases())
def monotone_in_m(f, case):
    flowers, k, m = case
    if f(flowers, k, m) and m > 1:
        assert f(flowers, k, m - 1) is True


@prop("Needing more flowers than exist (k * m > len(flowers)) is impossible.", case=cases())
def too_few_flowers(f, case):
    flowers, k, m = case
    m = len(flowers) // k + 1
    assert f(flowers, k, m) is False


@prop("Using exactly all flowers (k * m == len(flowers)) is possible once all have bloomed.",
      flowers=st.lists(days, min_size=1, max_size=15), data=st.data())
def exact_fit(f, flowers, data):
    n = len(flowers)
    k = data.draw(st.sampled_from([d for d in range(1, n + 1) if n % d == 0]))
    assert f(flowers, k, n // k) is True


@prop("Single-flower bouquets are possible iff m <= number of flowers.",
      flowers=st.lists(days, min_size=1, max_size=10), m=st.integers(1, 12))
def single_flower_bouquets(f, flowers, m):
    assert f(flowers, 1, m) is (m <= len(flowers))

reference_solution:
def can_make_bouquets(flowers, k, m):
    """
    Determine if it is possible to make m bouquets each consisting of k consecutive flowers.
    """
    def can_bloom(day):
        count = 0  # to keep track of consecutive blooming flowers
        bouquets = 0  # to keep track of bouquets made
        for bloom_day in flowers:
            if bloom_day <= day:
                count += 1
                if count == k:
                    bouquets += 1
                    count = 0
            else:
                count = 0
            if bouquets >= m:
                return True
        return False

    low, high = min(flowers), max(flowers)
    while low < high:
        mid = (low + high) // 2
        if can_bloom(mid):
            high = mid
        else:
            low = mid + 1

    return can_bloom(low)

