spec:
"""Spec for is_valid_expression: whether a string of brackets ()[]{} is balanced and properly nested.

Domain: strings over the six bracket characters, including the empty string (valid).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "is_valid_expression"

CLARIFICATIONS = [
    "Return a bool; the empty string is valid.",
]

PAIRS = ["()", "[]", "{}"]


def valid(s):
    prev = None
    while prev != s:
        prev = s
        for p in PAIRS:
            s = s.replace(p, "")
    return s == ""


@st.composite
def balanced(draw, depth=3):
    parts = draw(st.lists(st.sampled_from(PAIRS), min_size=0, max_size=3))
    out = ""
    for p in parts:
        inner = draw(balanced(depth - 1)) if depth > 0 and draw(st.booleans()) else ""
        out += p[0] + inner + p[1]
    return out


@st.composite
def corrupted(draw):
    s = draw(balanced())
    kind = draw(st.sampled_from(["drop", "insert", "swap", "flip"]))
    if not s or kind == "insert":
        k = draw(st.integers(0, len(s)))
        return s[:k] + draw(st.sampled_from("()[]{}")) + s[k:]
    k = draw(st.integers(0, len(s) - 1))
    if kind == "drop":
        return s[:k] + s[k + 1:]
    if kind == "flip":
        other = {"(": ")", ")": "(", "[": "]", "]": "[", "{": "}", "}": "{"}[s[k]]
        return s[:k] + other + s[k + 1:]
    j = draw(st.integers(0, len(s) - 1))
    t = list(s)
    t[k], t[j] = t[j], t[k]
    return "".join(t)


random_text = st.text(alphabet="()[]{}", max_size=12)


@prop("Properly nested, balanced strings are valid.", s=balanced())
def balanced_is_valid(f, s):
    assert f(s) is True


@prop("Strings with an odd length or a different number of openers and closers are invalid.", s=corrupted())
def unbalanced_is_invalid(f, s):
    opens = sum(s.count(c) for c in "([{")
    if len(s) % 2 == 1 or opens * 2 != len(s):
        assert f(s) is False


@prop("The result is a bool matching full validity on corrupted and random strings.", s=st.one_of(corrupted(), random_text))
def matches_definition(f, s):
    r = f(s)
    assert isinstance(r, bool)
    assert r == valid(s)


@prop("Crossed nesting of different bracket types is invalid.", s=balanced(), pair=st.permutations(PAIRS))
def crossing_invalid(f, s, pair):
    a, b = pair[0], pair[1]
    assert f(a[0] + b[0] + s + a[1] + b[1]) is False


@prop("The empty string is valid and a lone bracket is invalid.", c=st.sampled_from("()[]{}"))
def edge_cases(f, c):
    assert f("") is True
    assert f(c) is False

"""Spec for rearrange_string: a permutation of s in which equal characters are at least k positions apart, or "".

Domain: lowercase strings (up to 10 characters over a few letters), 0 <= k <= 4.
Interpretation (from the reference and unit tests): "no character repeats within any span of k
positions" means any two equal characters are at least k indices apart; k <= 1 imposes no constraint,
and k == 0 returns s unchanged.
"""
from collections import Counter

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "rearrange_string"

CLARIFICATIONS = [
    "The constraint is defined by k alone: any two equal characters must be at least k positions apart (their indices differ by >= k). For k <= 1 every rearrangement is valid.",
    "If k == 0, return s unchanged.",
    "Return \"\" if no valid rearrangement exists.",
]

texts = st.one_of(
    st.text(alphabet="abc", max_size=10),
    st.text(alphabet="ab", max_size=10),
    st.text(alphabet="abcd", max_size=10),
    st.builds(lambda c, n: c * n, st.sampled_from("az"), st.integers(1, 6)),
)
ks = st.integers(0, 4)


def ok(t, k):
    last = {}
    for i, c in enumerate(t):
        if c in last and i - last[c] < k:
            return False
        last[c] = i
    return True


def feasible(s, k):
    counts = Counter(s)
    n = len(s)

    def go(pos, last):
        if pos == n:
            return True
        for c in sorted(counts):
            if counts[c] and (c not in last or pos - last[c] >= k):
                counts[c] -= 1
                prev = last.get(c)
                last[c] = pos
                if go(pos + 1, last):
                    counts[c] += 1
                    if prev is None:
                        del last[c]
                    else:
                        last[c] = prev
                    return True
                counts[c] += 1
                if prev is None:
                    del last[c]
                else:
                    last[c] = prev
        return False

    return go(0, {})


@prop("The result is a string that is either empty or a rearrangement of s.", s=texts, k=ks)
def is_permutation_or_empty(f, s, k):
    r = f(s, k)
    assert isinstance(r, str)
    assert r == "" or sorted(r) == sorted(s)


@prop("A non-empty result keeps equal characters at least k positions apart.", s=texts, k=ks)
def respects_distance(f, s, k):
    r = f(s, k)
    assert r == "" or ok(r, k)


