    assert f([a], x) is False
    assert f([a], 2 * a) is False

reference_solution:
def has_pair_with_sum(arr, x):
    """
    Returns True if there exists a pair of elements in the array whose sum is equal to x.
    """
    seen = set()
    for num in arr:
        if x - num in seen:
            return True
        seen.add(num)
    return False

