"""Spec for min_path_sum: minimum total cost of a right/down path from the top-left to the bottom-right cell.

Domain: non-empty rectangular grids of non-negative integers (both endpoint cells are counted),
plus the empty grid [] exercised by the unit tests.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "min_path_sum"

CLARIFICATIONS = [
    "The path cost includes both the starting and the ending cell.",
    "Return 0 for an empty grid.",
]


@st.composite
def grids(draw, max_side=5):
    m = draw(st.integers(min_value=1, max_value=max_side))
    n = draw(st.integers(min_value=1, max_value=max_side))
    hi = draw(st.sampled_from([1, 9, 1000]))
    return [draw(st.lists(st.integers(min_value=0, max_value=hi), min_size=n, max_size=n)) for _ in range(m)]


def all_path_sums(grid, i=0, j=0):
    m, n = len(grid), len(grid[0])
    here = grid[i][j]
    if i == m - 1 and j == n - 1:
        return [here]
    out = []
    if i + 1 < m:
        out += [here + s for s in all_path_sums(grid, i + 1, j)]
    if j + 1 < n:
        out += [here + s for s in all_path_sums(grid, i, j + 1)]
    return out


@prop("The result is an int equal to the minimum over all right/down paths of the summed cell costs.", g=grids())
def matches_brute_force(f, g):
    r = f(g)
    assert isinstance(r, int)
    assert r == min(all_path_sums(g))


@prop("A single row or a single column has only one path: the sum of all cells.",
      cells=st.lists(st.integers(min_value=0, max_value=100), min_size=1, max_size=10), column=st.booleans())
def single_line(f, cells, column):
    g = [[c] for c in cells] if column else [cells]
    assert f(g) == sum(cells)


@prop("Transposing the grid does not change the minimum path sum.", g=grids())
def transpose_invariant(f, g):
    t = [list(col) for col in zip(*g)]
    assert f(g) == f(t)


@prop("The result is at least the two corner cells combined and at most the cost of any one path (e.g. right-then-down).", g=grids())
def bounds(f, g):
    r = f(g)
    corners = g[0][0] + (g[-1][-1] if len(g) * len(g[0]) > 1 else 0)
    right_then_down = sum(g[0]) + sum(row[-1] for row in g[1:])
    assert corners <= r <= right_then_down


@prop("A 1x1 grid returns its cell and an empty grid returns 0.", v=st.integers(min_value=0, max_value=10**6))
def degenerate(f, v):
    assert f([[v]]) == v
    assert f([]) == 0

"""Spec for num_islands: number of 4-connected components of '1' cells in a grid of '0'/'1' strings.

Domain: rectangular grids of the single-character strings '0' and '1' with at least one row and
column, plus the empty grid [] exercised by the unit tests.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "num_islands"

CLARIFICATIONS = [
    "Cells are the strings '1' and '0'. Return 0 for an empty grid.",
    "Diagonally adjacent cells are not connected.",
]


@st.composite
def grids(draw, max_side=7):
    m = draw(st.integers(min_value=1, max_value=max_side))
    n = draw(st.integers(min_value=1, max_value=max_side))
    p = draw(st.sampled_from([0.0, 0.3, 0.5, 0.7, 1.0]))
    return [[("1" if draw(st.floats(min_value=0, max_value=1, exclude_max=True)) < p else "0") for _ in range(n)] for _ in range(m)]


def count_components(grid):
    m, n = len(grid), len(grid[0]) if grid else 0
    parent = {(i, j): (i, j) for i in range(m) for j in range(n) if grid[i][j] == "1"}

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    for (i, j) in list(parent):
        for (a, b) in ((i + 1, j), (i, j + 1)):
            if (a, b) in parent:
                parent[find((a, b))] = find((i, j))
    return len({find(c) for c in parent})


@prop("The result is an int equal to the number of 4-connected groups of '1' cells.", g=grids())
def matches_components(f, g):
    r = f(g)
    assert isinstance(r, int)
    assert r == count_components(g)


@prop("Transposing or mirroring the grid does not change the island count.", g=grids())
def symmetry_invariant(f, g):
    base = f(g)
    assert f([list(col) for col in zip(*g)]) == base
    assert f([row[::-1] for row in g]) == base
    assert f(g[::-1]) == base


@prop("A checkerboard of '1' cells has one island per '1' (diagonals do not connect).",
      m=st.integers(min_value=1, max_value=7), n=st.integers(min_value=1, max_value=7), parity=st.integers(min_value=0, max_value=1))
def checkerboard(f, m, n, parity):
    g = [["1" if (i + j) % 2 == parity else "0" for j in range(n)] for i in range(m)]
    assert f(g) == sum(row.count("1") for row in g)


@prop("An all-'1' grid is one island and an all-'0' grid has none.",
      m=st.integers(min_value=1, max_value=8), n=st.integers(min_value=1, max_value=8))
def uniform_grids(f, m, n):
    assert f([["1"] * n for _ in range(m)]) == 1
    assert f([["0"] * n for _ in range(m)]) == 0


@prop("Separating rows of land with a row of water adds their island counts.", a=grids(), b=grids())
def disjoint_union(f, a, b):
    n = max(len(a[0]), len(b[0]))
    pad = lambda g: [row + ["0"] * (n - len(row)) for row in g]
    combined = pad(a) + [["0"] * n] + pad(b)
    assert f(combined) == f(a) + f(b)


@prop("An empty grid has 0 islands.", dummy=st.just(None))
def empty_grid(f, dummy):
    assert f([]) == 0

reference_solution:
def num_islands(grid):
    """
    Returns the number of distinct islands in the grid.
    An island is a group of connected '1's (occupied land) connected horizontally or vertically.
    """
    if not grid:
        return 0

    def dfs(x, y):
        if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] == '0':
            return
        grid[x][y] = '0'  # Mark the land as visited
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    islands_count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                islands_count += 1
                dfs(i, j)
    return islands_count

