spec:
"""Spec for has_pair_with_sum: whether two different elements of arr sum to k.

Domain: arr is a list of distinct integers (possibly empty or a single element); k is any integer.
An element may not be paired with itself.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "has_pair_with_sum"

CLARIFICATIONS = [
    "Return a bool; return False for an empty or single-element array.",
]

distinct_lists = st.one_of(
    st.lists(st.integers(min_value=-20, max_value=20), unique=True, max_size=12),
    st.lists(st.integers(min_value=-10**7, max_value=10**7), unique=True, max_size=12),
)


def oracle(arr, k):
    return any(arr[i] + arr[j] == k for i in range(len(arr)) for j in range(i + 1, len(arr)))


@st.composite
def case(draw):
    arr = draw(distinct_lists)
    mode = draw(st.sampled_from(["pair", "double", "random"]))
    if mode == "pair" and len(arr) >= 2:
        i, j = draw(st.lists(st.integers(0, len(arr) - 1), min_size=2, max_size=2, unique=True))
        k = arr[i] + arr[j]
    elif mode == "double" and arr:
        k = 2 * draw(st.sampled_from(arr))
    else:
        k = draw(st.integers(min_value=-40, max_value=40))
    return arr, k


@prop("The result is True exactly when two different elements sum to k.", c=case())
def matches_definition(f, c):
    arr, k = c
    assert f(arr, k) == oracle(arr, k)


@prop("The sum of any two distinct chosen elements is detected (result is True).", c=case())
def finds_existing_pair(f, c):
    arr, k = c
    if oracle(arr, k):
        assert f(arr, k) is True


@prop("An element is never paired with itself: k equal to twice a lone element gives False.",
      x=st.integers(min_value=-10**6, max_value=10**6), others=st.lists(st.integers(min_value=10**7, max_value=2 * 10**7), unique=True, max_size=5))
def no_self_pairing(f, x, others):
    arr = [x] + others
    assert f(arr, 2 * x) is False


@prop("Empty and single-element arrays give False.",
      x=st.one_of(st.none(), st.integers(min_value=-100, max_value=100)), k=st.integers(min_value=-200, max_value=200))
def too_short(f, x, k):
    arr = [] if x is None else [x]
    assert f(arr, k) is False


@prop("The result is a bool and does not depend on element order.", c=case(), data=st.data())
def bool_and_order_invariant(f, c, data):
    arr, k = c
    r = f(arr, k)
    assert isinstance(r, bool)
    assert f(list(data.draw(st.permutations(arr))), k) == r

"""Spec for numRescueBoats: minimum boats, each holding at most two people with total weight <= limit.

Domain: limit is a positive integer and every weight is an integer in 1..limit
(so everyone fits in a boat alone); people may be empty.
"""
from functools import lru_cache

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "numRescueBoats"

CLARIFICATIONS = [
    "Every person's weight is at most limit. Return 0 when there are no people.",
]


@st.composite
def case(draw, max_n=8):
    limit = draw(st.integers(min_value=1, max_value=20))
    w = st.one_of(st.integers(min_value=1, max_value=limit),
                  st.sampled_from(sorted({1, max(1, limit // 2), (limit + 1) // 2, limit})))
    people = draw(st.lists(w, max_size=max_n))
    return people, limit


def oracle(people, limit):
    @lru_cache(maxsize=None)
    def best(rest):
        if not rest:
            return 0
        first, others = rest[0], rest[1:]
        options = [1 + best(others)]
        for i, w in enumerate(others):
            if first + w <= limit:
                options.append(1 + best(others[:i] + others[i + 1:]))
        return min(options)

    return best(tuple(sorted(people)))


@prop("The result equals the true minimum number of boats.", c=case())
def is_minimum(f, c):
    people, limit = c
    assert f(people, limit) == oracle(people, limit)


@prop("The result is at least ceil(n / 2) and at most n.", c=case(max_n=30))
def within_bounds(f, c):
    people, limit = c
    r = f(people, limit)
    assert isinstance(r, int)
    assert (len(people) + 1) // 2 <= r <= len(people)


@prop("When any two people fit together, exactly ceil(n / 2) boats are needed.",
      people=st.lists(st.integers(min_value=1, max_value=50), max_size=30), extra=st.integers(min_value=0, max_value=10))
def everyone_pairs(f, people, extra):
    limit = 2 * max(people, default=1) + extra
    assert f(people, limit) == (len(people) + 1) // 2


@prop("When no two people fit together, everyone needs their own boat.",
      limit=st.integers(min_value=1, max_value=40), data=st.data())
def nobody_pairs(f, limit, data):
    people = data.draw(st.lists(st.integers(min_value=limit // 2 + 1, max_value=limit), max_size=15))
    assert f(people, limit) == len(people)


@prop("No people need 0 boats and one person needs 1 boat.",
      limit=st.integers(min_value=1, max_value=100), data=st.data())
def tiny_inputs(f, limit, data):
    w = data.draw(st.integers(min_value=1, max_value=limit))
    assert f([], limit) == 0
    assert f([w], limit) == 1


@prop("The answer does not depend on the order of the people.", c=case(max_n=15), data=st.data())
def order_invariant(f, c, data):
    people, limit = c
    assert f(list(data.draw(st.permutations(people))), limit) == f(people, limit)

