      a=st.integers(min_value=0, max_value=10**6), b=st.integers(min_value=0, max_value=10**6))
def tiny_inputs(f, a, b):
    assert f([]) == 0
    assert f([a]) == a
    assert f([a, b]) == max(a, b)


