spec:
"""Spec for reorder_sequence: for each query, alternately take the next smallest and next largest remaining element.

Domain: queries is a list of tuples (N, sequence) with N == len(sequence) >= 0. Every sequence is
given in non-decreasing order (as in all samples and unit tests), so taking from the left end is
the same as taking the smallest remaining number and from the right end the largest. Values are
positive integers. The unit tests include an empty sequence (0, []).
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "reorder_sequence"

CLARIFICATIONS = [
    "Each query's sequence is given in non-decreasing order.",
    "queries is a list of tuples (N, sequence); return a list containing one reordered list per query, in input order.",
    "An empty sequence (N = 0) yields an empty list.",
]

sequences = st.one_of(
    st.lists(st.integers(1, 10**9), max_size=25),
    st.lists(st.integers(1, 4), max_size=25),
    st.lists(st.integers(1, 10**9), min_size=1, max_size=2),
).map(sorted)
queries = st.lists(sequences.map(lambda s: (len(s), s)), min_size=1, max_size=5)


def alternate(seq):
    """Take from the remaining pool: smallest, largest, smallest, ... until empty."""
    pool = list(seq)
    out = []
    take_small = True
    while pool:
        out.append(pool.pop(pool.index(min(pool)) if take_small else len(pool) - 1 - pool[::-1].index(max(pool))))
        take_small = not take_small
    return out


@prop("The result is a list with one list per query.", queries=queries)
def one_list_per_query(f, queries):
    result = f(len(queries), queries)
    assert isinstance(result, list)
    assert len(result) == len(queries)
    assert all(isinstance(r, list) for r in result)


@prop("Each reordered sequence is a permutation of its input.", queries=queries)
def is_permutation(f, queries):
    for (_, seq), r in zip(queries, f(len(queries), queries)):
        assert sorted(r) == sorted(seq)


@prop("Each reordered sequence alternates smallest remaining, largest remaining, starting with the smallest.", queries=queries)
def alternates_min_max(f, queries):
    assert f(len(queries), queries) == [alternate(seq) for _, seq in queries]


@prop("The first element is the minimum and the second (if any) is the maximum.", seq=sequences.filter(len))
def starts_min_then_max(f, seq):
    (r,) = f(1, [(len(seq), seq)])
    assert r[0] == min(seq)
    if len(seq) > 1:
        assert r[1] == max(seq)


@prop("Queries are answered independently: each query alone gives the same result as within the batch.", queries=queries)
def queries_independent(f, queries):
    batch = f(len(queries), queries)
    assert batch == [f(1, [q])[0] for q in queries]


@prop("An empty sequence gives an empty list.", extra=st.lists(sequences.map(lambda s: (len(s), s)), max_size=2))
def empty_sequence(f, extra):
    result = f(1 + len(extra), [(0, [])] + extra)
    assert result[0] == []

"""Spec for largest_connected_component: size of the largest connected component of an undirected graph on vertices 1..n.

Domain: n >= 1, edges is a list of tuples (u, v) with 1 <= u, v <= n, u != v, and no pair of vertices
joined twice (in either orientation). Isolated vertices count as components of size 1.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "largest_connected_component"

CLARIFICATIONS = [
    "edges is a list of (u, v) tuples; vertices that appear in no edge are components of size 1.",
    "Return the size as an int.",
]


@st.composite
def graphs(draw, max_n=12):
    n = draw(st.integers(1, max_n))
    pairs = [(u, v) for u in range(1, n + 1) for v in range(u + 1, n + 1)]
    density = draw(st.sampled_from([0.0, 0.1, 0.25, 0.5, 1.0]))
    chosen = [p for p in pairs if draw(st.floats(0, 1)) < density] if pairs else []
    edges = [(v, u) if draw(st.booleans()) else (u, v) for u, v in chosen]
    edges = list(draw(st.permutations(edges)))
    return n, edges


def component_sizes(n, edges):
    """Label propagation: repeatedly give both ends of every edge the smaller label until stable."""
    label = list(range(n + 1))
    changed = True
    while changed:
        changed = False
        for u, v in edges:
            m = min(label[u], label[v])
            if label[u] != m or label[v] != m:
                label[u] = label[v] = m
                changed = True
    sizes = {}
    for x in range(1, n + 1):
        sizes[label[x]] = sizes.get(label[x], 0) + 1
    return sorted(sizes.values())


@prop("The result is an int equal to the size of the largest connected component.", g=graphs())
def matches_definition(f, g):
    n, edges = g
    result = f(n, edges)
    assert isinstance(result, int)
    assert result == component_sizes(n, edges)[-1]


@prop("With no edges the answer is 1.", n=st.integers(1, 1000))
def no_edges(f, n):
    assert f(n, []) == 1


@prop("A path through all vertices in any order gives n.", n=st.integers(1, 30), data=st.data())
def path_spans_all(f, n, data):
    order = data.draw(st.permutations(list(range(1, n + 1))))
    edges = [(order[i], order[i + 1]) for i in range(n - 1)]
    assert f(n, edges) == n


@prop("Renumbering the vertices does not change the answer.", g=graphs(), data=st.data())
def relabel_invariant(f, g, data):
    n, edges = g
    perm = data.draw(st.permutations(list(range(1, n + 1))))
    mapped = [(perm[u - 1], perm[v - 1]) for u, v in edges]
    assert f(n, mapped) == f(n, edges)


@prop("Adding isolated vertices does not change the answer.", g=graphs(), extra=st.integers(1, 5))
def isolated_vertices_ignored(f, g, extra):
    n, edges = g
    expected = component_sizes(n, edges)[-1]
    assert f(n + extra, edges) == expected


@prop("Two disjoint cliques: the answer is the larger clique size.", a=st.integers(1, 7), b=st.integers(1, 7))
def two_cliques(f, a, b):
    edges = [(u, v) for u in range(1, a + 1) for v in range(u + 1, a + 1)]
    edges += [(a + u, a + v) for u in range(1, b + 1) for v in range(u + 1, b + 1)]
    assert f(a + b, edges) == max(a, b)

reference_solution:
def largest_connected_component(n, edges):
    from collections import defaultdict

    def dfs(node, visited, graph):
        stack = [node]
        component_size = 0
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                component_size += 1
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return component_size

    # Building the graph as an adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    largest_size = 0

    for i in range(1, n + 1):
        if not visited[i]:
            component_size = dfs(i, visited, graph)
            largest_size = max(largest_size, component_size)

    return largest_size

