    "Return a list of n (x, y) pairs using 1-based coordinates; any valid placement and order is accepted.",
]

odd_n = st.one_of(st.integers(0, 99).map(lambda k: 2 * k + 1), st.sampled_from([1, 3, 5, 997, 999]))


def pairs(f, n):
