"""Spec for max_price_difference: for each 1-based inclusive range [L, R], max price minus min price in that range.

Domain: N == len(prices) >= 1, 1 <= price <= 10^6, Q == len(queries) >= 1, each query a tuple
(L, R) with 1 <= L <= R <= N.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "max_price_difference"

CLARIFICATIONS = [
    "L and R are 1-based and inclusive; queries is a list of (L, R) tuples.",
    "Return a list of ints, one per query, in query order.",
]


@st.composite
def instance(draw):
    n = draw(st.integers(1, 15))
    value = draw(st.sampled_from([st.integers(1, 10**6), st.integers(1, 4)]))
    prices = draw(st.lists(value, min_size=n, max_size=n))

    def query():
        left = draw(st.integers(1, n))
        kind = draw(st.sampled_from(["any", "single", "whole", "prefix", "suffix"]))
        if kind == "single":
            return (left, left)
        if kind == "whole":
            return (1, n)
        if kind == "prefix":
            return (1, draw(st.integers(1, n)))
        if kind == "suffix":
            return (left, n)
        return (left, draw(st.integers(left, n)))

    queries = [query() for _ in range(draw(st.integers(1, 8)))]
    return n, prices, queries


def spread(prices, l, r):
    seg = prices[l - 1:r]
    return max(seg) - min(seg)


@prop("The result is a list with one int per query.", inst=instance())
def one_answer_per_query(f, inst):
    n, prices, queries = inst
    result = f(n, prices, len(queries), queries)
    assert isinstance(result, list)
    assert len(result) == len(queries)
    assert all(isinstance(r, int) for r in result)


@prop("Each answer is the maximum minus the minimum of prices[L..R] (1-based, inclusive).", inst=instance())
def matches_definition(f, inst):
    n, prices, queries = inst
    assert f(n, prices, len(queries), queries) == [spread(prices, l, r) for l, r in queries]


@prop("A single-city range gives 0.", inst=instance(), data=st.data())
def single_city_zero(f, inst, data):
    n, prices, _ = inst
    i = data.draw(st.integers(1, n))
    assert f(n, prices, 1, [(i, i)]) == [0]


@prop("Widening a range never decreases the answer.", inst=instance(), data=st.data())
def monotone_in_range(f, inst, data):
    n, prices, _ = inst
    l = data.draw(st.integers(1, n))
    r = data.draw(st.integers(l, n))
    l2 = data.draw(st.integers(1, l))
    r2 = data.draw(st.integers(r, n))
    small, big = f(n, prices, 2, [(l, r), (l2, r2)])
    assert big >= small


@prop("The whole-array range gives max(prices) - min(prices).", inst=instance())
def whole_range(f, inst):
    n, prices, _ = inst
    assert f(n, prices, 1, [(1, n)]) == [max(prices) - min(prices)]

"""Spec for sumOfDistinctElements: per query, the sum of the distinct values >= d in nums[l..r] (1-based, inclusive).

Domain: 1 <= nums[i] <= 1000, 1 <= d <= 1000, queries is a list (possibly empty, as in the unit
tests) of tuples (l, r) with 1 <= l <= r <= len(nums). The statement's example outputs contain
arithmetic slips (19 and 18); its own explanations and the unit tests give 20 and 15.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "sumOfDistinctElements"

CLARIFICATIONS = [
    "Queries use 1-based inclusive indices: query (l, r) covers nums[l-1], ..., nums[r-1].",
    "Each distinct value is added once, however often it occurs in the range; return 0 if no value qualifies.",
    "The correct outputs for the examples are {12, 20} and {9, 15, 15}.",
    "Return a list of ints, one per query, in query order (an empty list for no queries).",
]


@st.composite
def instance(draw):
    n = draw(st.integers(1, 15))
    value = draw(st.sampled_from([st.integers(1, 1000), st.integers(1, 6)]))
    nums = draw(st.lists(value, min_size=n, max_size=n))
    d = draw(st.one_of(st.sampled_from(nums), st.integers(1, 1000), st.integers(1, 7)))

    def query():
        left = draw(st.integers(1, n))
        kind = draw(st.sampled_from(["any", "single", "whole"]))
        if kind == "single":
            return (left, left)
        if kind == "whole":
            return (1, n)
        return (left, draw(st.integers(left, n)))

    queries = [query() for _ in range(draw(st.integers(0, 6)))]
    return nums, d, queries


def answer(nums, d, l, r):
    seen = []
    for x in nums[l - 1:r]:
        if x >= d and x not in seen:
            seen.append(x)
    return sum(seen)


@prop("The result is a list with one int per query.", inst=instance())
def one_answer_per_query(f, inst):
    nums, d, queries = inst
    result = f(nums, d, queries)
    assert isinstance(result, list)
    assert len(result) == len(queries)
    assert all(isinstance(r, int) for r in result)


@prop("Each answer is the sum of the distinct values >= d in the 1-based inclusive range.", inst=instance())
def matches_definition(f, inst):
    nums, d, queries = inst
    assert f(nums, d, queries) == [answer(nums, d, l, r) for l, r in queries]


@prop("Values equal to d are included and values just below d are excluded.", v=st.integers(2, 1000), k=st.integers(1, 5))
def threshold_inclusive(f, v, k):
    nums = [v] * k + [v - 1]
    assert f(nums, v, [(1, k + 1)]) == [v]


@prop("Repeated values are counted once.", v=st.integers(1, 1000), k=st.integers(1, 10))
def duplicates_once(f, v, k):
    assert f([v] * k, 1, [(1, k)]) == [v]


@prop("If d exceeds every value, every answer is 0.", inst=instance())
def all_below_threshold(f, inst):
    nums, _, queries = inst
    assert f(nums, max(nums) + 1, queries) == [0] * len(queries)


@prop("No queries give an empty list.", inst=instance())
def no_queries(f, inst):
    nums, d, _ = inst
    assert f(nums, d, []) == []

"""Spec for manage_participants: process Add/Delete/Count queries and return the Count results in order.

Domain: queries is a list of strings "Add name score", "Delete name" or "Count lo hi" with names of
letters only, 1 <= score <= 10^7 and lo <= hi. Deleting an absent name does nothing; adding an
existing name replaces its score.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "manage_participants"

CLARIFICATIONS = [
    "queries is a list of query strings; return a list of ints holding the result of each Count query, in order (do not print).",
    "Deleting a name that is not in the list does nothing.",
]

names = st.sampled_from(["Alice", "Bob", "Charlie", "Dave", "Eve"])
scores = st.one_of(st.integers(1, 10), st.integers(1, 10**7))


@st.composite
def query(draw):
    kind = draw(st.sampled_from(["Add", "Add", "Delete", "Count"]))
    if kind == "Add":
        return f"Add {draw(names)} {draw(scores)}"
    if kind == "Delete":
        return f"Delete {draw(names)}"
    lo = draw(scores)
    hi = draw(st.one_of(st.just(lo), st.integers(lo, lo + 10), st.integers(lo, 10**7)))
    return f"Count {lo} {hi}"


query_lists = st.lists(query(), max_size=25)


def simulate(queries):
    """Replay the queries on an explicit list of (name, score) entries."""
    entries = []
    out = []
    for q in queries:
        parts = q.split()
        if parts[0] == "Add":
            entries = [e for e in entries if e[0] != parts[1]] + [(parts[1], int(parts[2]))]
        elif parts[0] == "Delete":
            entries = [e for e in entries if e[0] != parts[1]]
        else:
            lo, hi = int(parts[1]), int(parts[2])
            out.append(len([1 for _, s in entries if lo <= s <= hi]))
    return out


@prop("The result is a list with one int per Count query.", qs=query_lists)
def one_result_per_count(f, qs):
    result = f(qs)
    assert isinstance(result, list)
    assert len(result) == sum(q.startswith("Count") for q in qs)
    assert all(isinstance(r, int) for r in result)


@prop("Every Count result equals the number of current participants with lo <= score <= hi.", qs=query_lists)
def matches_simulation(f, qs):
    assert f(qs) == simulate(qs)


@prop("Re-adding a participant replaces their score instead of adding a second entry.", name=names, a=st.integers(1, 100), b=st.integers(1, 100))
def add_updates(f, name, a, b):
    assert f([f"Add {name} {a}", f"Add {name} {b}", "Count 1 100", f"Count {b} {b}"]) == [1, 1]


@prop("Deleting removes a participant; deleting an absent one changes nothing.", name=names, other=names, s=st.integers(1, 100))
def delete_behaviour(f, name, other, s):
    qs = [f"Add {name} {s}", f"Delete {other}", f"Count {s} {s}", f"Delete {name}", f"Count 1 100"]
    assert f(qs) == [0 if other == name else 1, 0]


@prop("Count bounds are inclusive at both ends.", s=st.integers(2, 10**7 - 1))
def inclusive_bounds(f, s):
    qs = [f"Add A {s}", f"Count {s} {s + 1}", f"Count {s - 1} {s}", f"Count {s + 1} {s + 2}", f"Count {s - 1} {s - 1}"]
    assert f(qs) == [1, 1, 0, 0]


@prop("With no Count queries the result is empty.", qs=st.lists(query().filter(lambda q: not q.startswith("Count")), max_size=10))
def no_counts(f, qs):
    assert f(qs) == []

"""Spec for shortest_completing_word: the shortest word containing every letter of target (case-insensitive, with multiplicity).

Domain: words is a non-empty list of lowercase alphabetic words; target is an ASCII string of letters,
digits, spaces and punctuation of length >= 1. Non-letters in target are ignored; letters are
compared case-insensitively.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "shortest_completing_word"

CLARIFICATIONS = [
    "If several completing words are equally short, return the one that appears first in words.",
    "Return None if no word is a completing word.",
]

word = st.text(alphabet="abcst", min_size=1, max_size=7)
word_lists = st.lists(word, min_size=1, max_size=10)
target = st.text(alphabet="abcstABCST0123 .,!", min_size=1, max_size=8)


def letters(t):
    return [c.lower() for c in t if c.isascii() and c.isalpha()]


def completes(w, t):
    need = letters(t)
    return all(w.count(c) >= need.count(c) for c in set(need))


def expected(words, t):
    best = None
    for w in words:
        if completes(w, t) and (best is None or len(w) < len(best)):
            best = w
    return best


@prop("The result is the first shortest completing word, or None if there is none.", words=word_lists, t=target)
def matches_definition(f, words, t):
    assert f(words, t) == expected(words, t)


@prop("A returned word is from the list and contains every target letter with multiplicity.", words=word_lists, t=target)
def result_completes(f, words, t):
    r = f(words, t)
    if r is not None:
        assert r in words
        assert completes(r, t)


@prop("No completing word in the list is shorter than the result, and None only if no word completes.", words=word_lists, t=target)
def result_is_shortest(f, words, t):
    r = f(words, t)
    lengths = [len(w) for w in words if completes(w, t)]
    if r is None:
        assert not lengths
    else:
        assert len(r) == min(lengths)


@prop("Among equally short completing words the earliest is returned.", w=word, data=st.data())
def first_on_ties(f, w, data):
    shuffled = "".join(data.draw(st.permutations(w)))
    assert f([w, shuffled], w.upper()) == w


@prop("Case, digits, spaces and punctuation in target do not matter.", words=word_lists, t=target)
def target_normalized(f, words, t):
    stripped = "".join(letters(t))
    assert f(words, t) == f(words, stripped.upper() + "1 2!") == f(words, stripped + "7")


@prop("A target letter missing from every word gives None.", words=word_lists, extra=target)
def missing_letter_none(f, words, extra):
    assert f(words, extra + "z") is None

"""Spec for unique_stones: per test case, the number of brilliance values that occur exactly once.

Domain: T == len(test_cases) >= 1; each test case is a tuple (N, B) with N == len(B) >= 1 and
0 <= B[i] <= 100000.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "unique_stones"

CLARIFICATIONS = [
    "test_cases is a list of tuples (N, B); return a list of ints, one answer per test case, in input order.",
]

values = st.one_of(
    st.lists(st.integers(0, 100000), min_size=1, max_size=30),
    st.lists(st.integers(0, 4), min_size=1, max_size=30),
    st.builds(lambda v, k: [v] * k, st.integers(0, 100000), st.integers(1, 10)),
    st.lists(st.integers(0, 100000), min_size=1, max_size=30, unique=True),
)
cases = st.lists(values.map(lambda b: (len(b), b)), min_size=1, max_size=5)


def singletons(b):
    return sum(1 for v in set(b) if b.count(v) == 1)


@prop("The result is a list with one int per test case.", cases=cases)
def one_answer_per_case(f, cases):
    result = f(len(cases), cases)
    assert isinstance(result, list)
    assert len(result) == len(cases)
    assert all(isinstance(r, int) for r in result)


@prop("Each answer is the number of values occurring exactly once.", cases=cases)
def matches_definition(f, cases):
    assert f(len(cases), cases) == [singletons(b) for _, b in cases]


@prop("All-distinct values keep every stone.", b=st.lists(st.integers(0, 100000), min_size=1, max_size=40, unique=True))
def all_distinct(f, b):
    assert f(1, [(len(b), b)]) == [len(b)]


@prop("Doubling every stone leaves none unique.", b=values)
def doubled_none(f, b):
    d = b + b
    assert f(1, [(len(d), d)]) == [0]


@prop("A value occurring two or more times is not unique; a value occurring once is.", v=st.integers(0, 100000), k=st.integers(2, 10))
def repeated_not_unique(f, v, k):
    assert f(1, [(k, [v] * k)]) == [0]
    assert f(1, [(k + 1, [v] * k + [v + 1])]) == [1]
